@app.exception_handler(HTTPException)
async def node_http_exception_handler(request: Request, exc: HTTPException):
    if (
        exc.status_code == 503
        and str(exc.detail) == MAIN_PANEL_DISCONNECTED_DETAIL
        and _browser_document_request(request)
    ):
        return _main_panel_disconnected_page(request)
    headers = {"Cache-Control": "no-store", **(exc.headers or {})}
    return JSONResponse({"detail": exc.detail}, status_code=exc.status_code, headers=headers)


# STREAMFORGE_NODE_PANEL_UNHANDLED_ERROR_PAGE_V103:
def _node_panel_temporary_error_page() -> HTMLResponse:
    page = '''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>Panel temporarily unavailable</title>
<style>*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden}body{min-height:100vh;min-height:100dvh;display:grid;place-items:center;padding:14px;background:#05090e;color:#edf4fb;font-family:system-ui,-apple-system,Segoe UI,sans-serif}.card{width:min(390px,calc(100vw - 24px));padding:24px 22px;border:1px solid #2b3a4d;border-radius:15px;background:#0b131d;box-shadow:0 16px 48px #0007;text-align:center}.card h2{margin:0 0 9px;font-size:clamp(18px,4.5vw,22px)}.card p{margin:0;color:#a9b9c8;line-height:1.45;font-size:clamp(11px,3vw,14px)}@media(max-width:420px){body{padding:9px}.card{width:calc(100vw - 18px);padding:20px 14px}}</style></head><body><section class="card"><h2>Panel temporarily unavailable</h2><p>Please retry in a moment.</p></section></body></html>'''
    return HTMLResponse(page, status_code=500, headers={"Cache-Control":"no-store","Retry-After":"2"})


@app.exception_handler(Exception)
async def node_unhandled_exception_handler(request: Request, exc: Exception):
    path = str(request.url.path or "/")[:300]
    try:
        manager.log(
            "Node panel request failed",
            scope="auth" if (path == "/" or "/panel" in path or path.endswith("/login")) else "system",
            level="error",
            user="Guest",
            details=f"ip={manager._client_ip(request)}; path={path}; error={type(exc).__name__}: {str(exc)[:1200]}",
        )
    except Exception:
        pass
    if _browser_document_request(request) and (path == "/" or "/panel" in path or path.endswith("/login")):
        return _node_panel_temporary_error_page()
    return JSONResponse({"detail":"Internal Server Error"}, status_code=500, headers={"Cache-Control":"no-store"})


def _request_authority(request: Request) -> tuple[str, int | None]:
    # STREAMFORGE_NODE_FORWARDED_AUTHORITY_V35: chained TLS proxies may pass
    # the original public host/port while the Node itself receives HTTP.
    value = (request.headers.get("x-forwarded-host") or request.headers.get("host") or "").split(",", 1)[0].strip()
    forwarded_port = (request.headers.get("x-forwarded-port") or "").split(",", 1)[0].strip()
    explicit_port: int | None = None
    if value.startswith("["):
        end = value.find("]")
        host = value[1:end].strip().lower().rstrip(".") if end > 0 else ""
        if end > 0 and len(value) > end + 1 and value[end + 1] == ":":
            try:
                explicit_port = int(value[end + 2:])
            except ValueError:
                explicit_port = None
    elif value.count(":") == 1:
        host, raw_port = value.rsplit(":", 1)
        host = host.strip().lower().rstrip(".")
        try:
            explicit_port = int(raw_port)
        except ValueError:
            host = value.strip().lower().rstrip(".")
    else:
        host = value.strip().lower().rstrip(".")
    if explicit_port is not None:
        return host, explicit_port
    try:
        return host, int(forwarded_port) if forwarded_port else None
    except ValueError:
        return host, None


def _request_host(request: Request) -> str:
    return _request_authority(request)[0]


def _valid_control_token(request: Request) -> bool:
    candidate = request.headers.get("x-node-token") or ""
    return bool(TOKEN and candidate and hmac.compare_digest(candidate, TOKEN))


def _match_access_url(
    host: str,
    request_port: int | None,
    path: str,
    values: list[str],
) -> tuple[bool, str, str]:
    """Match the most-specific configured path on one public authority."""
    # STREAMFORGE_NODE_LONGEST_PLAYLIST_ALIAS_V3040:
    # A root alias matches every path, so returning the first list match makes
    # it shadow a later alias such as /12 on the same host and port.  Collect
    # all authority/path matches and select the longest public prefix.  Stable
    # list order remains the tie-breaker for equivalent aliases.
    matches: list[tuple[int, int, str, str]] = []
    for index, value in enumerate(values):
        try:
            parsed = urllib.parse.urlsplit(str(value or "").strip())
        except ValueError:
            continue
        expected_host = (parsed.hostname or "").lower().rstrip(".")
        try:
            expected_port = parsed.port
        except ValueError:
            continue
        if not expected_host or host != expected_host:
            continue
        default_port = 443 if parsed.scheme == "https" else 80
        # Browsers commonly omit an explicit default :80/:443 from the Host
        # header. Treat the absent Host port as the URL scheme's default so
        # ``http://host:80/path`` and ``http://host/path`` match identically.
        if int(request_port or default_port) != int(expected_port or default_port):
            continue
        prefix = parsed.path.rstrip("/")
        if prefix:
            if path != prefix and not path.startswith(prefix + "/"):
                continue
            stripped = path[len(prefix):] or "/"
        else:
            stripped = path
        matches.append((len(prefix), -index, stripped, prefix))
    if matches:
        _length, _order, stripped, prefix = max(matches, key=lambda item: (item[0], item[1]))
        return True, stripped, prefix
    return False, path, ""


def _access_url_match(request: Request, values: list[str]) -> tuple[bool, str, str]:
    """Return match state, internal path and the exact matched public prefix."""
    host, request_port = _request_authority(request)
    path = str(request.scope.get("path") or request.url.path or "/")
    return _match_access_url(host, request_port, path, values)


def _route_kind(path: str) -> str:
    if path == "/" or path.startswith("/panel") or path.startswith("/node-logos/"):
        return "panel"
    if path.startswith("/api/v1/"):
        return "control"
    if path == "/update.json" or (path.count("/") == 1 and path.lower().endswith(".apk")):
        return "stream"
    if path.startswith(("/playlist/", "/node-play/", "/_sf-media/", "/player_api.php", "/get.php", "/live/", "/web-player", "/channel-logos/")):
        return "stream"
    # STREAMFORGE_NODE_LEGACY_XTREAM_DIRECT_ROUTE_V127:
    # Older Xtream clients commonly request /username/password/id.m3u8 (or .ts)
    # instead of /live/username/password/id.ext. Treat that narrow three-part
    # form as public streaming traffic so the outer fail-closed middleware and
    # Nginx public plane do not misclassify it as a control-panel request.
    if re.fullmatch(r"/[^/]+/[^/]+/[0-9]+\.(?:m3u8|ts)", path, re.I):
        return "stream"
    return "other"


def _scope_header(scope: dict[str, Any], name: bytes) -> str:
    for key, value in scope.get("headers") or []:
        if bytes(key).lower() == name:
            try:
                return bytes(value).decode("latin-1").strip()
            except Exception:
                return ""
    return ""


# STREAMFORGE_NODE_LIVE_SESSION_KILL_CANONICAL_POST_V1044:
def _clean_live_session_kill_id(value: Any) -> str:
    """Normalize the browser-supplied SID used only for allow-listed kill dispatch."""
    return re.sub(r"[^A-Za-z0-9._~-]+", "", str(value or "").strip())[:96]


# STREAMFORGE_NODE_HIDDEN_POST_DISPATCH_V53: POSTs from the browser-visible
# Panel/API root must be validated against the hidden internal route too.
# Otherwise the outer silent-host middleware aborts the request before the
# FastAPI hidden-route dispatcher can map Settings/forms to /panel/....
def _scope_cookie_value(scope: dict[str, Any], name: str) -> str:
    raw = _scope_header(scope, b"cookie")
    if not raw:
        return ""
    wanted = str(name or "").strip()
    for item in raw.split(";"):
        key, sep, value = item.strip().partition("=")
        if sep and key == wanted:
            return value.strip().strip('"')
    return ""


def _scope_hidden_node_panel_target(scope: dict[str, Any]) -> str:
    return _normalize_hidden_node_panel_target(
        _scope_cookie_value(scope, STREAMFORGE_NODE_PANEL_ROUTE_COOKIE)
    )


def _scope_authority(scope: dict[str, Any]) -> tuple[str, int | None]:
    value = (_scope_header(scope, b"x-forwarded-host") or _scope_header(scope, b"host")).split(",", 1)[0].strip()
    forwarded_port = _scope_header(scope, b"x-forwarded-port").split(",", 1)[0].strip()
    explicit_port: int | None = None
    if value.startswith("["):
        end = value.find("]")
        host = value[1:end].strip().lower().rstrip(".") if end > 0 else ""
        if end > 0 and len(value) > end + 1 and value[end + 1] == ":":
            try:
                explicit_port = int(value[end + 2:])
            except ValueError:
                explicit_port = None
    elif value.count(":") == 1:
        host, raw_port = value.rsplit(":", 1)
        host = host.strip().lower().rstrip(".")
        try:
            explicit_port = int(raw_port)
        except ValueError:
            host = value.strip().lower().rstrip(".")
    else:
        host = value.strip().lower().rstrip(".")
    if explicit_port is not None:
        return host, explicit_port
    try:
        return host, int(forwarded_port) if forwarded_port else None
    except ValueError:
        return host, None


def _scope_public_scheme(scope: dict[str, Any]) -> str:
    forwarded = _scope_header(scope, b"x-forwarded-proto").split(",", 1)[0].strip().lower()
    if forwarded in {"http", "https"}:
        return forwarded
    scheme = str(scope.get("scheme") or "http").strip().lower()
    return scheme if scheme in {"http", "https"} else "http"


def _scope_is_acme_challenge(scope: dict[str, Any]) -> bool:
    path = str(scope.get("path") or "")
    return bool(
        scope.get("type") == "http"
        and str(scope.get("method") or "GET").upper() in {"GET", "HEAD"}
        and path.startswith("/.well-known/acme-challenge/")
    )


def _scope_is_local_tls_proxy(scope: dict[str, Any]) -> bool:
    # STREAMFORGE_NODE_LOCAL_TLS_PROXY_TRUST_V39: only trust our marker when
    # the TCP peer itself is loopback. A public client cannot spoof this header
    # to bypass the configured scheme/listener policy on the native HTTP port.
    if _scope_header(scope, b"x-streamforge-node-tls-proxy").strip() != "1":
        return False
    client = scope.get("client")
    host = str(client[0] if isinstance(client, (tuple, list)) and client else "")
    try:
        return ipaddress.ip_address(host).is_loopback
    except ValueError:
        return False


def _scope_canonical_protocol_redirect(scope: dict[str, Any]) -> str:
    """Return a Node canonical-protocol redirect target, preserving path/query."""
    # STREAMFORGE_NODE_CANONICAL_PROTOCOL_REDIRECT_V35:
    if scope.get("type") != "http" or _valid_scope_control_token(scope):
        return ""
    request_scheme = _scope_public_scheme(scope)
    host, request_port = _scope_authority(scope)
    if not host:
        return ""
    actual_port = int(request_port or (443 if request_scheme == "https" else 80))
    path = str(scope.get("path") or "/")
    candidates: list[tuple[int, int, str, str]] = []
    rows: list[tuple[str, str, int]] = []
    for role, values in (("panel", list(manager.panel_urls or [])), ("stream", list(manager.stream_urls or []))):
        for index, value in enumerate(values):
            rows.append((role, str(value or "").strip(), index))
    for role, value, index in rows:
        try:
            parsed = urllib.parse.urlsplit(value)
            expected_host = (parsed.hostname or "").lower().rstrip(".")
            expected_port = int(parsed.port or (443 if parsed.scheme == "https" else 80))
        except (TypeError, ValueError):
            continue
        if parsed.scheme not in {"http", "https"} or expected_host != host:
            continue
        prefix = parsed.path.rstrip("/")
        if prefix:
            if path != prefix and not path.startswith(prefix + "/"):
                continue
            stripped = path[len(prefix):] or "/"
        else:
            stripped = path
        route_kind = _route_kind(stripped)
        if role == "stream":
            serves = stripped == "/" or route_kind == "stream"
        else:
            serves = stripped == "/" or route_kind != "stream"
        if not serves:
            continue
        if parsed.scheme == request_scheme and expected_port == actual_port:
            return ""
        if parsed.scheme != request_scheme:
            candidates.append((len(prefix), -index, parsed.scheme, parsed.netloc))
    if not candidates:
        return ""
    _prefix_len, _order, target_scheme, target_netloc = max(candidates, key=lambda item: (item[0], item[1]))
    query = bytes(scope.get("query_string") or b"").decode("latin-1")
    return urllib.parse.urlunsplit((target_scheme, target_netloc, path, query, ""))


def _scope_access_url_match(scope: dict[str, Any], values: list[str]) -> tuple[bool, str, str]:
    host, request_port = _scope_authority(scope)
    path = str(scope.get("path") or "/")
    return _match_access_url(host, request_port, path, values)


def _node_panel_public_redirect_location(
    location: str,
    prefix: str,
    stream_public_prefixes: set[str],
) -> str:
    """Translate an internal Panel redirect to its configured public alias."""
    location_targets_stream = bool(
        location.startswith("/")
        and any(
            public_prefix
            and (location == public_prefix or location.startswith(public_prefix + "/"))
            for public_prefix in stream_public_prefixes
        )
    )
    if location_targets_stream:
        return location
    panel_root = prefix or "/"
    if location == "/panel":
        return panel_root
    if location.startswith("/panel?"):
        return panel_root + location[len("/panel"):]
    if location.startswith("/panel/"):
        return prefix + location[len("/panel"):]
    if location.startswith("/panel-play"):
        return prefix + location
    if location == "/":
        return panel_root
    if (
        location.startswith("/")
        and location != prefix
        and not location.startswith(prefix + "/")
    ):
        return prefix + location
    return location


def _valid_scope_control_token(scope: dict[str, Any]) -> bool:
    candidate = _scope_header(scope, b"x-node-token")
    return bool(TOKEN and candidate and hmac.compare_digest(candidate, TOKEN))


def _internal_media_auth_scope(scope: dict[str, Any]) -> bool:
    if str(scope.get("path") or "") != "/_internal/node-media-auth":
        return False
    if _scope_header(scope, b"x-streamforge-media-auth") != "1":
        return False
    client = scope.get("client") or ("", 0)
    try:
        return ipaddress.ip_address(str(client[0] or "")).is_loopback
    except ValueError:
        return False


def _node_internal_route_exists(path: str, method: str = "GET") -> bool:
    """Return True only when the resolved internal path has a real FastAPI route."""
    inner_app = getattr(app, "app", app)
    router = getattr(inner_app, "router", None)
    if router is None:
        return False
    normalized_method = str(method or "GET").upper()
    for route in getattr(router, "routes", []):
        path_regex = getattr(route, "path_regex", None)
        if path_regex is None or path_regex.match(path) is None:
            continue
        methods = getattr(route, "methods", None)
        if not methods:
            return True
        if normalized_method in methods or (normalized_method == "HEAD" and "GET" in methods):
            return True
    return False


def _node_access_should_silently_drop(scope: dict[str, Any]) -> bool:
    """Reject invalid public Node authorities before FastAPI emits an HTTP page."""
    if scope.get("type") != "http" or _valid_scope_control_token(scope) or _internal_media_auth_scope(scope):
        return False
    panel_urls = list(getattr(manager, "panel_urls", []) or [])
    stream_urls = list(getattr(manager, "stream_urls", []) or [])
    # A freshly installed Node must remain reachable by the authenticated Main
    # bootstrap API. Until an access policy arrives, retain legacy open-host
    # behaviour for unauthenticated requests as well.
    if not panel_urls and not stream_urls:
        return False

    original_path = str(scope.get("path") or "/")
    panel_match, panel_path, panel_prefix = _scope_access_url_match(scope, panel_urls)
    stream_match, stream_path, _stream_prefix = _scope_access_url_match(scope, stream_urls)
    # STREAMFORGE_NODE_ROOT_PANEL_PREFIX_EXCLUSION_V3059:
    # With a root Panel/API URL, /panel is private implementation routing and
    # must not be accepted as a second public Panel address.  If /panel itself
    # is explicitly configured as an alias, longest-prefix matching gives it a
    # non-empty prefix and it remains available.
    if (
        panel_match
        and not panel_prefix
        and (original_path == "/panel" or original_path.startswith("/panel/"))
    ):
        return True
    # STREAMFORGE_NODE_HIDDEN_POST_DISPATCH_V53: root-visible native
    # navigation keeps forms/AJAX on the public root. Resolve the allow-listed
    # internal POST target before deciding whether the request is valid.
    method = str(scope.get("method") or "GET").upper()
    if panel_match and panel_path == "/" and method not in {"GET", "HEAD"}:
        action = _scope_header(scope, b"x-streamforge-panel-action").strip().lower()
        if action == "source-scan":
            panel_path = "/source-scan.json"
        elif action == "live-session-kill":
            kill_sid = _clean_live_session_kill_id(_scope_header(scope, b"x-streamforge-live-session-id"))
            panel_path = f"/sessions/{kill_sid}/kill" if kill_sid else "/__invalid-live-session-kill__"
        else:
            hidden_target = _scope_hidden_node_panel_target(scope)
            if hidden_target:
                panel_path = urllib.parse.urlsplit(hidden_target).path or "/panel"
    panel_kind = _route_kind(panel_path)
    stream_kind = _route_kind(stream_path)

    # STREAMFORGE_NODE_PANEL_UNKNOWN_SILENT_DROP_V2198:
    # Resolve the public Node Panel/API alias to its internal FastAPI route.
    # Unknown descendants such as /admin/test are aborted by the outer ASGI
    # middleware instead of returning 404 or being exposed as a normal page.
    panel_internal_path = panel_path
    if panel_match and panel_kind == "other":
        panel_internal_path = "/panel" if panel_path == "/" else "/panel" + panel_path
    valid_panel = bool(
        panel_match
        and _node_internal_route_exists(
            panel_internal_path,
            str(scope.get("method") or "GET"),
        )
    )
    valid_stream = bool(
        stream_match
        and (
            stream_path == "/"
            or (
                stream_kind == "stream"
                and _node_internal_route_exists(
                    stream_path,
                    str(scope.get("method") or "GET"),
                )
            )
        )
    )

    if NODE_MODE == "public":
        return not valid_stream
    if NODE_MODE == "panel":
        return not valid_panel
    if NODE_MODE == "control":
        # STREAMFORGE_NODE_MULTI_ALIAS_PORT_ROUTING_V59: each configured URL
        # already matches its own hostname, scheme-facing forwarded port and
        # optional path.  Do not gate all Playlist/App aliases by the legacy
        # scalar ``stream_port`` derived from the first URL.  That broke mixed
        # aliases such as https://cnbox.tv (443) + http://iptv.cnbox.tv (80).
        return not (valid_panel or valid_stream)

    # Unknown modes fail closed once aliases are configured.
    return not (valid_panel or valid_stream)


async def _abort_asgi_connection(send: Any) -> None:
    """Close Uvicorn's client transport without sending an HTTP response."""
    cycle = getattr(send, "__self__", None)
    transport = getattr(cycle, "transport", None)
    if cycle is not None:
        try:
            cycle.disconnected = True
        except Exception:
            pass
    if transport is not None:
        try:
            transport.abort()
        except Exception:
            try:
                transport.close()
            except Exception:
                pass
        await asyncio.sleep(0)
        return
    # Non-Uvicorn ASGI test servers do not expose a transport. Status 444 is a
    # no-body fallback and is never used by the production Node service.
    await send({
        "type": "http.response.start",
        "status": 444,
        "headers": [(b"content-length", b"0"), (b"connection", b"close"), (b"cache-control", b"no-store")],
    })
    await send({"type": "http.response.body", "body": b"", "more_body": False})


class SilentInvalidNodeAccessMiddleware:
    def __init__(self, app: Any) -> None:
        self.app = app

    async def __call__(self, scope: dict[str, Any], receive: Any, send: Any) -> None:
        # STREAMFORGE_NODE_PUBLIC_OUTER_ACCESS_RELOAD_V1151:
        # The silent access guard is the outermost ASGI middleware.  In v11.50
        # the inner FastAPI middleware refreshed access.json, but a newly added
        # Panel/Playlist alias could never reach that inner layer: this outer
        # guard still held the worker's startup snapshot and aborted the socket,
        # which Nginx surfaced as 502.  Refresh once here before any canonical
        # URL or silent-drop decision.  Internal media-auth subrequests bypass
        # the stat/read path so the HLS fast path stays unchanged.
        if scope.get("type") == "http" and not _internal_media_auth_scope(scope):
            manager.refresh_runtime_access_if_changed()

        # STREAMFORGE_NODE_UNKNOWN_ICON_QUIET_404_V1147:
        # Unknown /icon/* asset probes are not application routes. Aborting the
        # upstream transport makes Nginx emit "upstream prematurely closed" for
        # every request and can fill a small Node disk in hours. Return a small
        # cacheable 404; real Panel/API paths retain the fail-closed policy.
        if scope.get("type") == "http" and str(scope.get("path") or "").startswith("/icon/"):
            await send({
                "type": "http.response.start",
                "status": 404,
                "headers": [
                    (b"content-length", b"0"),
                    (b"cache-control", b"public, max-age=300"),
                    (b"x-streamforge-version", VERSION.encode("latin-1")),
                ],
            })
            await send({"type": "http.response.body", "body": b"", "more_body": False})
            return
        # ACME HTTP-01 must remain reachable on the native HTTP listener even
        # when the hostname's canonical public scheme is HTTPS.
        if _scope_is_acme_challenge(scope):
            await self.app(scope, receive, send)
            return
        # STREAMFORGE_NODE_INTERNAL_MEDIA_AUTH_CANONICAL_BYPASS_V1034:
        # Nginx auth_request talks to the private Public backend over loopback HTTP,
        # even when the viewer-facing Playlist/App alias is HTTPS. Never canonical-
        # redirect this authenticated internal subrequest: auth_request accepts 2xx
        # (or 401/403 for denial) and treats a 307 redirect as an upstream error.
        # _internal_media_auth_scope() still requires the private header and loopback.
        if _internal_media_auth_scope(scope):
            await self.app(scope, receive, send)
            return
        canonical_protocol_target = _scope_canonical_protocol_redirect(scope)
        if canonical_protocol_target:
            location = canonical_protocol_target.encode("latin-1")
            await send({
                "type": "http.response.start",
                "status": 307,
                "headers": [
                    (b"location", location),
                    (b"cache-control", b"no-store, no-cache, must-revalidate"),
                    (b"pragma", b"no-cache"),
                    (b"x-streamforge-version", VERSION.encode("latin-1")),
                    (b"x-streamforge-route", b"node-canonical-protocol-redirect"),
                ],
            })
            await send({"type": "http.response.body", "body": b"", "more_body": False})
            return
        if _node_access_should_silently_drop(scope):
            await _abort_asgi_connection(send)
            return
        await self.app(scope, receive, send)


def _bootstrap_settings_path(request: Request) -> str | None:
    path = str(request.scope.get("path") or request.url.path or "/")
    suffix = "/api/v1/settings/sync"
    if _valid_control_token(request) and path.endswith(suffix):
        return suffix
    return None


# STREAMFORGE_NODE_GENERIC_NETWORK_BLOCK_PAGE_V98:
# STREAMFORGE_NODE_CENTERED_NETWORK_BLOCK_PAGE_V98R3:
def _node_public_block_logo_src() -> str:
    """Return a logo source that does not require an allowed secondary Node route.

    The restricted page can be rendered on the public Playlist/App authority while
    /node-logos/* is classified as a Panel route.  Embed synchronized local logos
    directly so the blocked page never shows a broken image icon.
    """
    logo = str(getattr(manager, "node_logo_url", "") or "").strip()
    prefix = "/node-logos/"
    if logo.startswith(prefix):
        raw_name = logo[len(prefix):]
        filename = Path(raw_name).name
        if filename and filename == raw_name:
            path = NODE_LOGO_ROOT / filename
            if path.is_file():
                try:
                    data = path.read_bytes()
                except OSError:
                    data = b""
                if data and len(data) <= 2 * 1024 * 1024:
                    mime = {
                        ".png": "image/png",
                        ".jpg": "image/jpeg",
                        ".jpeg": "image/jpeg",
                        ".webp": "image/webp",
                        ".gif": "image/gif",
                    }.get(path.suffix.lower())
                    if mime:
                        return f"data:{mime};base64,{base64.b64encode(data).decode('ascii')}"
    if logo.startswith(("https://", "http://")):
        return logo
    return ""


