@app.middleware("http")
async def enforce_node_access(request, call_next):
    original_path = str(request.scope.get("path") or request.url.path or "/")

    # STREAMFORGE_NODE_ACME_MIDDLEWARE_BYPASS_V40: HTTP-01 must bypass both
    # the outer silent-host/canonical middleware and this FastAPI access
    # middleware.  v3.9 bypassed only the outer layer, so a valid Certbot
    # webroot token could still be rewritten/rejected here and return 404.
    if _scope_is_acme_challenge(request.scope):
        return await call_next(request)
    # STREAMFORGE_NODE_NGINX_MEDIA_AUTH_BYPASS_V65: only the loopback Nginx
    # auth_request subrequest may reach this internal endpoint.
    if _internal_media_auth_scope(request.scope):
        return await call_next(request)

    # STREAMFORGE_NODE_PUBLIC_INTERNAL_HEALTH_V80: the dedicated public
    # Gunicorn pool is loopback-only. Its installer readiness probe carries
    # the Node token and must be allowed to reach the normal health route even
    # though public mode rejects all other control/API routes. This keeps the
    # public plane fail-closed externally while giving systemd/SSH installs a
    # real application-level readiness check instead of a socket-only probe.
    if NODE_MODE == "public" and original_path == "/api/v1/health" and _valid_control_token(request):
        try:
            public_health_loopback = ipaddress.ip_address(
                str(request.client.host if request.client else "")
            ).is_loopback
        except ValueError:
            public_health_loopback = False
        if public_health_loopback:
            return await call_next(request)

    # STREAMFORGE_NODE_PUBLIC_ACCESS_RUNTIME_RELOAD_V97R2:
    # Historical compatibility marker. v11.51 supersedes the old inner reload
    # implementation by refreshing access.json in the outer fail-closed guard
    # before hostname/path validation; the capability remains preserved.
    # STREAMFORGE_NODE_PUBLIC_ACCESS_RUNTIME_RELOAD_V1151:
    # The outer SilentInvalidNodeAccessMiddleware already refreshed access.json
    # before it decided whether this request may enter FastAPI.  Do not stat the
    # file a second time here on every public request.

    # STREAMFORGE_NODE_SLUG_PAIR_CANONICAL_V2190:
    # Repair the broken /<panel>/<playlist> form using the persisted legacy
    # access slugs themselves. This does not depend on panel_urls/stream_urls,
    # so it still works if an older proxy/config has already produced the
    # combined path before this request reaches the Node application.
    panel_slug = str(getattr(manager, "access_slug", "") or "").strip().strip("/")
    stream_slug = str(getattr(manager, "stream_slug", "") or "").strip().strip("/")
    if not panel_slug and manager.panel_urls:
        panel_slug = urllib.parse.urlsplit(str(manager.panel_urls[0] or "")).path.strip("/")
    if not stream_slug and manager.stream_urls:
        stream_slug = urllib.parse.urlsplit(str(manager.stream_urls[0] or "")).path.strip("/")

    if panel_slug and stream_slug:
        broken_prefix = f"/{panel_slug}/{stream_slug}"
        canonical_prefix = f"/{stream_slug}"
        if original_path == broken_prefix or original_path.startswith(broken_prefix + "/"):
            target = canonical_prefix + original_path[len(broken_prefix):]
            query = str(request.scope.get("query_string") or b"", "latin-1")
            if query:
                target += "?" + query
            return RedirectResponse(
                target,
                status_code=307,
                headers={
                    "Cache-Control": "no-store, no-cache, must-revalidate",
                    "Pragma": "no-cache",
                    "X-StreamForge-Version": VERSION,
                    "X-StreamForge-Route": "slug-pair-canonical-playlist",
                },
            )

    # STREAMFORGE_NODE_CANONICAL_PLAYLIST_PATH_V2189:
    # Repair any stale/cached cross-role URL such as /admin/stream or
    # /admin/stream/web-player before normal access matching. If a configured
    # Panel/API prefix is immediately followed by a configured Playlist/App
    # prefix on the same authority, the Playlist/App prefix is canonical.
    host, request_port = _request_authority(request)
    panel_prefixes: list[str] = []
    stream_prefixes: list[str] = []
    for value in list(manager.panel_urls or []):
        parsed = urllib.parse.urlsplit(str(value or "").strip())
        default_port = 443 if parsed.scheme == "https" else 80
        if (
            (parsed.hostname or "").lower().rstrip(".") == host
            and int(request_port or default_port) == int(parsed.port or default_port)
        ):
            prefix = parsed.path.rstrip("/")
            if prefix and prefix not in panel_prefixes:
                panel_prefixes.append(prefix)
    for value in list(manager.stream_urls or []):
        parsed = urllib.parse.urlsplit(str(value or "").strip())
        default_port = 443 if parsed.scheme == "https" else 80
        if (
            (parsed.hostname or "").lower().rstrip(".") == host
            and int(request_port or default_port) == int(parsed.port or default_port)
        ):
            prefix = parsed.path.rstrip("/")
            if prefix not in stream_prefixes:
                stream_prefixes.append(prefix)

    if original_path.startswith("/"):
        for panel_prefix in sorted(panel_prefixes, key=len, reverse=True):
            suffix = original_path[len(panel_prefix):] if original_path.startswith(panel_prefix) else ""
            if not suffix or not suffix.startswith("/"):
                continue
            for stream_prefix in sorted(stream_prefixes, key=len, reverse=True):
                if not stream_prefix:
                    continue
                if suffix == stream_prefix or suffix.startswith(stream_prefix + "/"):
                    target = suffix
                    query = str(request.scope.get("query_string") or b"", "latin-1")
                    if query:
                        target += "?" + query
                    return RedirectResponse(
                        target,
                        status_code=307,
                        headers={
                            "Cache-Control": "no-store",
                            "X-StreamForge-Version": VERSION,
                            "X-StreamForge-Route": "canonical-playlist-path",
                        },
                    )

    # Root Playlist/App alias: strip a matching Panel/API prefix from known
    # public player/playlist routes as a final stale-URL compatibility repair.
    if "" in stream_prefixes:
        known_stream_suffixes = (
            "/web-player", "/playlist/", "/node-play/", "/_sf-media/", "/player_api.php",
            "/get.php", "/live/", "/channel-logos/",
        )
        for panel_prefix in sorted(panel_prefixes, key=len, reverse=True):
            if original_path.startswith(panel_prefix + "/"):
                suffix = original_path[len(panel_prefix):]
                if any(suffix == item.rstrip("/") or suffix.startswith(item) for item in known_stream_suffixes):
                    query = str(request.scope.get("query_string") or b"", "latin-1")
                    target = suffix + (("?" + query) if query else "")
                    return RedirectResponse(
                        target,
                        status_code=307,
                        headers={
                            "Cache-Control": "no-store",
                            "X-StreamForge-Version": VERSION,
                            "X-StreamForge-Route": "canonical-root-playlist-path",
                        },
                    )

    bootstrap_path = _bootstrap_settings_path(request)
    if bootstrap_path:
        request.scope["path"] = bootstrap_path
        request.scope["raw_path"] = bootstrap_path.encode("utf-8")
        return await call_next(request)

    panel_match, panel_path, panel_prefix = _access_url_match(request, manager.panel_urls)
    stream_match, stream_path, stream_prefix = _access_url_match(request, manager.stream_urls)
    kind = "other"
    matched = False
    resolved_path = original_path
    panel_kind = _route_kind(panel_path)
    stream_kind = _route_kind(stream_path)
    # STREAMFORGE_NODE_PLAYLIST_ROOT_PRIORITY_V2187:
    # Exact Playlist/App root wins over any broader Panel/API alias on the
    # same authority. This prevents /stream becoming /admin/stream/web-player.
    if stream_match and stream_path == "/":
        # STREAMFORGE_NODE_PLAYLIST_ROOT_IP_WHITELIST_V97R2:
        # The exact Playlist/App root is rendered directly from middleware and
        # used to return before the common access_allowed() block below. That
        # allowed a non-whitelisted client to see the complete Node Web Player
        # catalogue even though its playback requests were later rejected.
        # Enforce the same IP/ASN access policy before rendering any catalogue.
        allowed, reason = manager.access_allowed(request)
        if not allowed:
            manager.log(f"Client access denied — {reason}", scope="client", level="warning", user="Guest", details=f"user=Guest; ip={manager._client_ip(request)}; path={original_path}; reason={reason}")
            return _node_public_network_blocked_response()
        # STREAMFORGE_NODE_DIRECT_PLAYLIST_PLAYER_V2188:
        # Serve the Web Player at the exact Playlist/App URL itself. Returning
        # the HTML here avoids every Panel/API redirect-rewrite branch.
        # STREAMFORGE_NODE_AUTO_LOGIN_ROOT_V2225:
        # The configured Playlist/App root is served directly from middleware.
        # It must use the same auto/manual login resolver as /web-player;
        # cookie-only lookup bypassed Auto Login completely.
        # STREAMFORGE_NODE_WEBPLAYER_FLASH_ERROR_V1082:
        # A legacy ?error= URL is cleaned before rendering.  New failures arrive
        # through the one-shot HttpOnly flash cookie and are consumed here.
        legacy_error = str(request.query_params.get("error") or "").strip()[:240]
        flash_path = stream_prefix.rstrip("/") or "/"
        if legacy_error:
            response = RedirectResponse(
                original_path,
                status_code=303,
                headers={"Cache-Control": "no-store, no-cache, must-revalidate, max-age=0"},
            )
            response.set_cookie(
                _NODE_WEB_FLASH_COOKIE,
                _node_web_flash_code(legacy_error),
                httponly=True,
                samesite="lax",
                secure=request.url.scheme == "https",
                max_age=30,
                path=flash_path,
            )
            return response
        flash_code = str(request.cookies.get(_NODE_WEB_FLASH_COOKIE) or "").strip()
        flash_error = _node_web_flash_message(request)
        user = _node_web_current_user(request)
        auto_log_marker = _node_web_log_auto_login_once(request, user)
        response = HTMLResponse(
            _node_web_page(user, request, flash_error),
            headers={
                "Cache-Control": "no-store",
                "X-StreamForge-Version": VERSION,
                "X-StreamForge-Route": "playlist-root-web-player",
                "X-StreamForge-WebPlayer-Login": str(_node_webplayer_effective_controls(request)["login_mode"]),
            },
        )
        if flash_code:
            response.delete_cookie(_NODE_WEB_FLASH_COOKIE, path=flash_path)
        if auto_log_marker:
            response.set_cookie(
                _NODE_WEB_AUTO_LOG_COOKIE,
                auto_log_marker,
                httponly=True,
                samesite="lax",
                secure=request.url.scheme == "https",
                max_age=43200,
                path="/",
            )
        return response
    elif panel_match and panel_path == "/":
        # STREAMFORGE_NODE_ROOT_LOGIN_REDIRECT_V87: an unauthenticated browser
        # at a root Panel/API URL must not replay a hidden route cookie into a
        # permission-protected handler that returns JSON 401.
        if request.method.upper() in {"GET", "HEAD"} and not _session_user(request):
            resolved_path = "/panel/login"
            kind, matched = "panel", True
        else:
            # STREAMFORGE_NODE_HIDDEN_NATIVE_ROUTE_V50
            action = str(request.headers.get("x-streamforge-panel-action") or "").strip().lower()
            if request.method.upper() == "POST" and action == "source-scan":
                resolved_path = "/panel/source-scan.json"
            elif request.method.upper() == "POST" and action == "live-session-kill":
                kill_sid = _clean_live_session_kill_id(request.headers.get("x-streamforge-live-session-id"))
                resolved_path = f"/panel/sessions/{kill_sid}/kill" if kill_sid else "/panel/sessions/__invalid-live-session-kill__/kill"
            else:
                hidden_target = _normalize_hidden_node_panel_target(request.cookies.get(STREAMFORGE_NODE_PANEL_ROUTE_COOKIE))
                if hidden_target:
                    hidden_parts = urllib.parse.urlsplit(hidden_target)
                    resolved_path = hidden_parts.path or "/panel"
                    if request.method.upper() in {"GET", "HEAD"}:
                        request.scope["query_string"] = hidden_parts.query.encode("utf-8")
                else:
                    resolved_path = "/panel"
            kind, matched = "panel", True
    elif panel_match and panel_kind == "control":
        kind, matched, resolved_path = "control", True, panel_path
    elif panel_match and panel_kind == "panel":
        # Legacy /<access>/panel URLs and /panel-play routes remain valid.
        kind, matched, resolved_path = "panel", True, panel_path
    elif stream_match and stream_kind == "stream":
        kind, matched, resolved_path = "stream", True, stream_path
    elif panel_match and panel_kind == "other":
        # The configured Panel/API URL is the dashboard itself.  Externally,
        # /admin, /admin/login and /admin/manage/channels map to the existing
        # internal /panel route tree without exposing an extra /panel segment.
        kind, matched = "panel", True
        resolved_path = "/panel" if panel_path == "/" else "/panel" + panel_path
    else:
        raw_kind = _route_kind(original_path)
        if raw_kind != "other":
            kind = raw_kind
        elif original_path.endswith("/panel") or "/panel/" in original_path:
            kind = "panel"
        elif "/api/v1/" in original_path:
            kind = "control"
        elif original_path.endswith("/update.json") or original_path.lower().endswith(".apk"):
            kind = "stream"
        elif any(part in original_path for part in ("/playlist/", "/node-play/", "/_sf-media/", "/player_api.php", "/get.php", "/live/", "/web-player")):
            kind = "stream"

    if NODE_MODE == "public" and kind != "stream":
        return Response(status_code=404, headers={"Cache-Control": "no-store", "Connection": "close"})
    if NODE_MODE == "panel" and kind == "stream":
        return Response(status_code=404, headers={"Cache-Control": "no-store", "Connection": "close"})
    # STREAMFORGE_NODE_MULTI_ALIAS_PORT_ROUTING_V59: access matching above
    # already proves that this exact Playlist/App alias owns the request's
    # host/port/path.  A single legacy stream_port must not reject a second
    # valid alias on port 80/443/custom ports.

    local_control = False
    if kind == "control" and _valid_control_token(request):
        try:
            local_control = ipaddress.ip_address(str(request.client.host if request.client else "")).is_loopback
        except ValueError:
            local_control = False
    required_urls = manager.stream_urls if kind == "stream" else manager.panel_urls if kind in {"panel", "control"} else []
    native_token_control = bool(NODE_MODE == "control" and kind == "control" and _valid_control_token(request))
    if kind in {"panel", "control", "stream"} and not local_control and not native_token_control and (not required_urls or not matched):
        detail = "Use a configured Playlist/App URL" if kind == "stream" else "Use a configured Node Panel/API URL"
        headers = {"Cache-Control": "no-store"}
        if kind == "panel" or "text/html" in (request.headers.get("accept") or ""):
            return HTMLResponse(
                f"<!doctype html><html><body style='background:#0b0f14;color:#edf4fb;font:16px system-ui;padding:32px'><h2>Access URL required</h2><p>{html.escape(detail)}.</p></body></html>",
                status_code=421, headers=headers,
            )
        return JSONResponse({"detail": detail}, status_code=421, headers=headers)

    active_prefix = stream_prefix if kind == "stream" and stream_match else panel_prefix if kind in {"panel", "control"} and panel_match else ""
    if matched and resolved_path != original_path:
        request.scope["path"] = resolved_path
        request.scope["raw_path"] = resolved_path.encode("utf-8")
        request.scope["root_path"] = active_prefix

    internal_api = kind == "control" and _valid_control_token(request)
    if not internal_api:
        # STREAMFORGE_NODE_PANEL_PLAYBACK_WHITELIST_SPLIT_V98:
        # Panel/API browser access uses its own IP whitelist; Playlist/App
        # traffic keeps the playback IP/ASN access rules.
        if kind in {"panel", "control"}:
            allowed, reason = manager.panel_access_allowed(request)
        else:
            allowed, reason = manager.access_allowed(request)
        if not allowed:
            path_lower = str(original_path or "").lower()
            if kind == "stream" and ("/web-player" in path_lower or path_lower.endswith("/get.php") or path_lower.endswith("/player_api.php") or "/playlist/" in path_lower):
                attempted_user = str(request.query_params.get("username") or "").strip() or "Guest"
                manager.log(f"Client access denied — {reason}", scope="client", level="warning", user=attempted_user, details=f"user={attempted_user}; ip={manager._client_ip(request)}; path={original_path}; reason={reason}")
            # STREAMFORGE_NODE_PANEL_DENY_DIAGNOSTIC_LOG_V102:
            # Keep the public blocked page generic, but record enough operator
            # detail to diagnose accidental IP/ASN lockouts. Only resolve ASN
            # when a Panel ASN rule is configured, avoiding unnecessary GeoIP
            # lookups on pure IP-policy denials.
            if kind in {"panel", "control"}:
                denied_ip = manager._client_ip(request)
                panel_needs_asn = bool(manager.panel_asn_whitelist.strip() or manager.panel_asn_blacklist.strip())
                try:
                    denied_asn = manager._lookup_asn(denied_ip) if panel_needs_asn else None
                    asn_text = f"AS{denied_asn}" if denied_asn is not None else ("unknown" if panel_needs_asn else "not-required")
                except Exception as exc:
                    # STREAMFORGE_NODE_PANEL_POLICY_DIAGNOSTIC_SAFE_V103:
                    # Diagnostics must never turn an intended 403 into a raw 500.
                    asn_text = "lookup-error"
                    reason = f"{reason}; diagnostic={type(exc).__name__}"
                manager.log(
                    "Panel access denied",
                    scope="auth",
                    level="warning",
                    user="Guest",
                    details=f"user=Guest; ip={denied_ip}; asn={asn_text}; path={original_path}; reason={reason}",
                )
            headers = {"Cache-Control": "no-store"}
            if kind == "stream" and "text/html" in (request.headers.get("accept") or ""):
                return _node_public_network_blocked_response()
            if kind == "panel" or "text/html" in (request.headers.get("accept") or ""):
                return _node_panel_network_blocked_response()
            return JSONResponse({"detail": reason}, status_code=403, headers=headers)
    panel_context = _CURRENT_PANEL_PREFIX.set(panel_prefix if panel_match else None)
    stream_context = _CURRENT_STREAM_PREFIX.set(stream_prefix if stream_match else None)
    try:
        response = await call_next(request)
        response.headers["X-StreamForge-Version"] = VERSION
    finally:
        _CURRENT_PANEL_PREFIX.reset(panel_context)
        _CURRENT_STREAM_PREFIX.reset(stream_context)
    # STREAMFORGE_NODE_ROOT_PANEL_ALIAS_V3058:
    # Redirects from internal /panel routes must also be canonicalized when
    # the configured public Panel/API prefix is empty (the authority root).
    if matched and (active_prefix or (kind == "panel" and panel_match)):
        prefix = active_prefix
        location = response.headers.get("location") or ""

        # STREAMFORGE_NODE_CROSS_ROLE_REDIRECT_V2186:
        # Do not prepend the current Panel/API prefix to a redirect that already
        # targets a configured Playlist/App prefix on the same authority.
        stream_public_prefixes = {
            urllib.parse.urlsplit(str(value or "").strip()).path.rstrip("/")
            for value in list(manager.stream_urls or [])
            if str(value or "").strip()
        }
        if kind == "panel":
            response.headers["location"] = _node_panel_public_redirect_location(
                location, prefix, stream_public_prefixes
            )
        elif location.startswith("/") and location != prefix and not location.startswith(prefix + "/"):
            response.headers["location"] = prefix + location
    return response


@app.post("/api/v1/settings/sync", dependencies=[Depends(authorized)])
def sync_access_settings(payload: AccessSettingsPayload):
    try:
        return manager.sync_access(payload)
    except ValueError as exc:
        raise HTTPException(400, str(exc)) from exc


@app.get("/api/v1/webplayer/users", dependencies=[Depends(authorized)])
def webplayer_local_users():
    # STREAMFORGE_NODE_WEBPLAYER_USER_LIST_API_V2224:
    # Return active Node-local users only. Password hashes are never returned.
    manager.reload_users_if_changed()
    with manager.lock:
        items = [
            user for user in manager.users.values()
            if str(user.source or "").strip().lower() == "node_local"
            and manager.valid_user(user.token)
        ]
    items.sort(key=lambda user: ((user.name or user.username).lower(), user.username.lower()))
    return {
        "ok": True,
        "users": [
            {
                "token": user.token,
                "name": user.name or user.username,
                "username": user.username,
                "expires_at": user.expires_at or "",
            }
            for user in items
        ],
    }


@app.post("/api/v1/users/sync", dependencies=[Depends(authorized)])
def sync_users(payload: UserSyncPayload):
    return manager.sync_users(payload)


@app.post("/api/v1/panel-users/sync", dependencies=[Depends(authorized)])
def sync_panel_users(payload: PanelUserSyncPayload):
    return manager.sync_panel_users(payload)


@app.post("/api/v1/agent/update", dependencies=[Depends(authorized)])
async def update_agent(request: Request, x_streamforge_version: str | None = Header(default=None)):
    # API uploads run as the unprivileged streamforge-node user and cannot
    # rewrite /etc/systemd/system. The first migration to /usr/bin/gunicorn
    # therefore must use the saved SSH installer; later code-only updates may
    # continue through this endpoint once the Gunicorn unit is installed.
    unit_path = Path("/etc/systemd/system/streamforge-node.service")
    try:
        unit_text = unit_path.read_text(encoding="utf-8", errors="replace")
    except OSError:
        unit_text = ""
    if "ExecStart=/usr/bin/gunicorn app:app" not in unit_text:
        raise HTTPException(409, "Gunicorn systemd migration requires a saved SSH Node update")
    # STREAMFORGE_NODE_V39_ROOT_TLS_UPDATE_GUARD: v3.9 adds root-owned Certbot,
    # Nginx and systemd components which an unprivileged API code upload cannot
    # install. Force one SSH/manual update rather than report a partial success.
    requested_version = str(x_streamforge_version or "").strip()
    if requested_version in {"3.9", "4.0", "4.1", "4.2", "4.3", "4.4"} and (
        not Path("/etc/systemd/system/streamforge-node-tls.service").is_file()
        or not Path("/opt/streamforge-node/apply_node_tls.py").is_file()
    ):
        raise HTTPException(409, "StreamForge Node managed TLS/ACME updates require one SSH/manual Node update")
    if requested_version == "6.5" and (
        shutil.which("redis-server") is None
        or not Path("/usr/local/libexec/streamforge-node/apply_node_tls.py").is_file()
        or "STREAMFORGE_NODE_NGINX_DIRECT_MEDIA_V65" not in Path("/usr/local/libexec/streamforge-node/apply_node_tls.py").read_text(encoding="utf-8", errors="ignore")
    ):
        raise HTTPException(409, "StreamForge v6.5 Node high-concurrency components require one SSH/manual Node update")
    # STREAMFORGE_NODE_V77_ROOT_NGINX_PLAYLIST_GUARD: v7.7+ changes the root-owned
    # Nginx direct-media / installer path and requires SSH/manual root update.
    _node_root_tls_helper = Path("/usr/local/libexec/streamforge-node/apply_node_tls.py")
    _node_root_tls_text = _node_root_tls_helper.read_text(encoding="utf-8", errors="ignore") if _node_root_tls_helper.is_file() else ""
    if requested_version in {"7.7", "7.8", "7.9", "8.0", "8.1", "8.2", "8.3", "8.4", "8.5", "8.6", "8.7", "8.8", "8.9", "9.0", "9.1", "9.2", "9.3", "9.4"} and (
        not _node_root_tls_helper.is_file()
        or "STREAMFORGE_NODE_LIVE_PLAYLIST_NO_OPEN_FILE_CACHE_V77" not in _node_root_tls_text
        # STREAMFORGE_NODE_V91_ROOT_HEARTBEAT_GUARD: v9.1 changes the root-owned
        # Nginx live-playlist auth cache, so an API-only agent copy is not enough.
        or (requested_version == "9.1" and "STREAMFORGE_NODE_LAST_ACTIVITY_2S_V91" not in _node_root_tls_text)
    ):
        raise HTTPException(409, "StreamForge v9.1 Node Nginx/session heartbeat fix requires one SSH/manual Node update" if requested_version == "9.1" else "StreamForge v7.7+ Node system fix requires one SSH/manual Node update")
    # STREAMFORGE_NODE_V79_PUBLIC_SYSTEMD_ROOT_GUARD: v7.9 moves the public
    # worker pool into a root-installed systemd unit; code-only API updates may
    # proceed only after that root migration exists.
    if requested_version in {"7.9", "8.0", "8.1", "8.2", "8.3", "8.4", "8.5", "8.6", "8.7", "8.8", "8.9", "9.0", "9.1", "9.2", "9.3", "9.4"} and (
        not Path("/etc/systemd/system/streamforge-node-public.service").is_file()
        or not Path("/opt/streamforge-node/public_start.py").is_file()
    ):
        raise HTTPException(409, "StreamForge v7.9+ Node public-service split requires one SSH/manual Node update")
    # STREAMFORGE_NODE_V123_PUBLIC_START_ROOT_GUARD:
    # v12.3 changes the systemd-owned public_start.py worker-sizing logic. An
    # API-only code upload does not carry that file, so force one SSH/manual update.
    if requested_version == "12.3":
        public_start_file = Path("/opt/streamforge-node/public_start.py")
        public_start_text = public_start_file.read_text(encoding="utf-8", errors="ignore") if public_start_file.is_file() else ""
        if "STREAMFORGE_NODE_PUBLIC_DESIRED_FFMPEG_RESERVE_V123" not in public_start_text:
            raise HTTPException(409, "StreamForge v12.3 Node public worker sizing requires one SSH/manual Node update")
    body = await request.body()
    if not body or len(body) > 10 * 1024 * 1024:
        raise HTTPException(400, "Invalid or oversized update package")
    root = Path(__file__).resolve().parent
    backup_root = Path("/var/lib/streamforge-node/backups")
    backup_root.mkdir(parents=True, exist_ok=True)
    backup = backup_root / f"agent-{int(time.time())}"
    backup.mkdir(parents=True, exist_ok=True)
    for name in ("app.py", "redis_state.py", "requirements.txt", "VERSION"):
        source = root / name
        if source.exists():
            shutil.copy2(source, backup / name)
    try:
        with tempfile.TemporaryDirectory(prefix="sf-node-update-") as temp_dir:
            temp = Path(temp_dir)
            import io
            with zipfile.ZipFile(io.BytesIO(body)) as archive:
                names = set(archive.namelist())
                if not {"app.py", "redis_state.py", "requirements.txt"}.issubset(names):
                    raise ValueError("Update package is missing app.py, redis_state.py or requirements.txt")
                temp_root = temp.resolve()
                for name in names:
                    candidate = (temp / name).resolve()
                    if candidate != temp_root and temp_root not in candidate.parents:
                        raise ValueError("Unsafe update archive")
                archive.extractall(temp)
            compile((temp / "app.py").read_text(encoding="utf-8"), "app.py", "exec")

            # STREAMFORGE_NODE_REQUIREMENTS_SKIP_V2193:
            # API updates should not reinstall the same Python plugins on every
            # version. Bootstrap the stamp from the currently installed
            # requirements file so upgrading from pre-stamp builds can skip once.
            incoming_requirements = temp / "requirements.txt"
            stamp_file = Path("/var/lib/streamforge-node/.python-requirements.sha256")
            incoming_hash = hashlib.sha256(incoming_requirements.read_bytes()).hexdigest()
            current_hash = ""
            try:
                current_hash = stamp_file.read_text(encoding="utf-8").strip()
            except OSError:
                current_requirements = root / "requirements.txt"
                if current_requirements.is_file():
                    current_hash = hashlib.sha256(current_requirements.read_bytes()).hexdigest()

            if current_hash == incoming_hash:
                manager.log("Node Python dependencies unchanged; skipping pip install", scope="update")
            else:
                pip_command = [sys.executable, "-m", "pip", "install", "--no-cache-dir", "--ignore-installed", "--upgrade", "-r", str(incoming_requirements)]
                pip_help = subprocess.run(
                    [sys.executable, "-m", "pip", "help", "install"],
                    check=False,
                    capture_output=True,
                    text=True,
                    timeout=30,
                )
                if "--break-system-packages" in (pip_help.stdout + pip_help.stderr):
                    pip_command.insert(4, "--break-system-packages")
                subprocess.run(pip_command, check=True, timeout=240)

            stamp_file.parent.mkdir(parents=True, exist_ok=True)
            stamp_file.write_text(incoming_hash + "\n", encoding="utf-8")
            for name in ("app.py", "redis_state.py", "requirements.txt", "VERSION"):
                source = temp / name
                if source.exists():
                    shutil.copy2(source, root / name)

            cache_clear_source = temp / "cache_clear.sh"
            if cache_clear_source.is_file():
                cache_clear_target = Path("/usr/local/sbin/streamforge-cache-clear")
                shutil.copy2(cache_clear_source, cache_clear_target)
                cache_clear_target.chmod(0o755)

            # STREAMFORGE_NODE_SELF_HOSTED_HLSJS_UPDATE_V1163:
            # Cache HLS.js during the update so public browser playback is not
            # dependent on a third-party CDN after the Node returns online.
            hls_fetch_source = temp / "fetch_hlsjs.sh"
            if hls_fetch_source.is_file():
                try:
                    subprocess.run(
                        ["/usr/bin/env", "bash", str(hls_fetch_source), str(WEBPLAYER_HLSJS_FILE)],
                        check=False,
                        timeout=60,
                    )
                except (OSError, subprocess.SubprocessError):
                    pass
    except Exception as exc:
        raise HTTPException(400, f"Node update failed: {exc}") from exc

    # STREAMFORGE_NODE_UPDATE_ZERO_CHANNEL_RESTART_V1083:
    # From v10.83 onward, code-only API updates hand running FFmpeg processes
    # to the replacement control worker.  The outgoing worker must not execute
    # the normal shutdown path that intentionally terminates all encoders.
    preserved_encoders = manager.prepare_update_ffmpeg_handoff(x_streamforge_version or "")
    manager.reload_http_workers_after_code_update()
    _NODE_UPDATE_RESTART_ARMED.set()

    def restart_self() -> None:
        time.sleep(1.5)
        os.kill(os.getpid(), signal.SIGTERM)

    manager.log(
        "Node Agent update package accepted", scope="update",
        details=f"target={x_streamforge_version or 'unknown'}; preserved_encoders={preserved_encoders}",
    )
    threading.Thread(target=restart_self, daemon=True).start()
    return {
        "ok": True,
        "updating": True,
        "from_version": VERSION,
        "target_version": x_streamforge_version or "unknown",
        "preserved_encoders": preserved_encoders,
        "zero_channel_restart": True,
    }


def require_panel_and_user(
    token: str, request: Request, *, enforce_connection: bool = False, session_id: str = "", playback_start: bool = False
) -> NodeUserConfig:
    if not manager.panel_connected() and not manager.independent_mode:
        raise HTTPException(503, "Main panel is disconnected; node user authentication is disabled")
    user = manager.valid_user(token)
    if not user:
        raise HTTPException(403, "Node user disabled or expired")
    if user.user_type == "restream":
        ip_text = manager._client_ip(request)
        if not user.restream_allowed_ips.strip() or not manager._ip_in_rules(ip_text, user.restream_allowed_ips):
            raise HTTPException(403, "This IP is not allowed for the restream account")
    if enforce_connection and not manager.allow_connection(user, request, session_id=session_id, playback_start=playback_start):
        raise HTTPException(429, "Connection limit reached")
    return user


# v1.11.116 eight-character Node playback grants. The short handle is random
# and IP-bound; the protected account/channel/expiry data remains in memory.
_NODE_PLAYBACK_KEY_LENGTH = 8
_NODE_PLAYBACK_KEY_ALPHABET = string.ascii_letters + string.digits
_node_playback_key_lock = threading.RLock()
_node_playback_grants: dict[str, dict[str, Any]] = {}
_node_playback_index: dict[tuple[str, str, str, str], str] = {}
_node_playback_last_cleanup = 0.0
_node_playback_loaded = False
_node_playback_persist_timer: threading.Timer | None = None


def _load_node_playback_keys_locked() -> None:
    global _node_playback_loaded
    if _node_playback_loaded:
        return
    _node_playback_loaded = True
    try:
        raw = json.loads(PLAYBACK_KEYS_FILE.read_text(encoding="utf-8"))
    except Exception:
        raw = {}
    now = time.time()
    for short_key, item in (raw.items() if isinstance(raw, dict) else []):
        if len(str(short_key)) != _NODE_PLAYBACK_KEY_LENGTH or not str(short_key).isalnum() or not isinstance(item, dict):
            continue
        if float(item.get("exp") or 0) < now:
            continue
        user_token = str(item.get("user_token") or "")
        channel_key = str(item.get("channel_key") or "")
        ip_text = str(item.get("ip") or "")
        sid = str(item.get("sid") or "")[:96]
        if not user_token or not channel_key or not ip_text:
            continue
        index_key = (user_token, channel_key, ip_text, sid)
        grant = dict(item)
        grant["index_key"] = index_key
        _node_playback_grants[str(short_key)] = grant
        _node_playback_index[index_key] = str(short_key)


def _persist_node_playback_keys() -> None:
    global _node_playback_persist_timer
    with _node_playback_key_lock:
        _node_playback_persist_timer = None
        now = time.time()
        payload = {
            key: {name: value for name, value in grant.items() if name != "index_key"}
            for key, grant in _node_playback_grants.items()
            if float(grant.get("exp") or 0) >= now
        }
    try:
        PLAYBACK_KEYS_FILE.parent.mkdir(parents=True, exist_ok=True)
        temporary = PLAYBACK_KEYS_FILE.with_name(f".{PLAYBACK_KEYS_FILE.name}.{secrets.token_hex(4)}.tmp")
        temporary.write_text(json.dumps(payload, separators=(",", ":")), encoding="utf-8")
        os.chmod(temporary, 0o600)
        temporary.replace(PLAYBACK_KEYS_FILE)
    except OSError:
        pass


def _schedule_node_playback_persist_locked() -> None:
    global _node_playback_persist_timer
    if _node_playback_persist_timer is not None:
        return
    _node_playback_persist_timer = threading.Timer(0.25, _persist_node_playback_keys)
    _node_playback_persist_timer.daemon = True
    _node_playback_persist_timer.start()


def _cleanup_node_playback_keys(now: float) -> None:
    global _node_playback_last_cleanup
    _load_node_playback_keys_locked()
    if now - _node_playback_last_cleanup < 30 and len(_node_playback_grants) < 250_000:
        return
    changed = False
    for short_key in [key for key, grant in _node_playback_grants.items() if float(grant.get("exp") or 0) < now]:
        grant = _node_playback_grants.pop(short_key, None)
        if grant:
            changed = True
            index_key = grant.get("index_key")
            if index_key and _node_playback_index.get(index_key) == short_key:
                _node_playback_index.pop(index_key, None)
    if changed:
        _schedule_node_playback_persist_locked()
    _node_playback_last_cleanup = now


def issue_node_playback_key(user: NodeUserConfig, channel: NodeUserChannel, request: Request, session_id: str) -> str:
    now = time.time()
    ttl = NODE_RESTREAM_KEY_TTL_SECONDS if user.user_type == "restream" else NODE_PLAYBACK_KEY_TTL_SECONDS
    ip_text = manager._client_ip(request)
    resolved_session_id = manager.request_session_id(request, session_id)
    # STREAMFORGE_NODE_SESSION_PLAYBACK_GRANT_V65: one playback handle is
    # shared by all channels in the same user/IP/session catalogue. Large M3U
    # playlists therefore create O(sessions), not O(sessions * channels),
    # runtime grants. Channel permission is still revalidated when resolved.
    index_key = (user.token, "*", ip_text, resolved_session_id)
    grant = {
        "user_token": user.token, "channel_key": "*", "ip": ip_text,
        "exp": int(now) + int(ttl), "sid": resolved_session_id,
    }
    # STREAMFORGE_NODE_REDIS_PLAYBACK_KEYS_V65: every public worker resolves
    # the same playback grants without rewriting playback-keys.json.
    if node_redis is not None and node_redis.available:
        try:
            return node_redis.issue_playback(
                "|".join(index_key), grant, int(ttl),
                _NODE_PLAYBACK_KEY_ALPHABET, _NODE_PLAYBACK_KEY_LENGTH,
            )
        except RuntimeError:
            pass
    if NODE_MODE == "public" and NODE_PUBLIC_WORKER_COUNT > 1:
        raise HTTPException(503, "Node Redis runtime state is unavailable")
    with _node_playback_key_lock:
        _cleanup_node_playback_keys(now)
        existing_key = _node_playback_index.get(index_key)
        existing = _node_playback_grants.get(existing_key or "")
        if existing and int(existing.get("exp") or 0) > int(now) + 60:
            return str(existing_key)
        for _attempt in range(128):
            short_key = "".join(secrets.choice(_NODE_PLAYBACK_KEY_ALPHABET) for _ in range(_NODE_PLAYBACK_KEY_LENGTH))
            if short_key not in _node_playback_grants:
                break
        else:
            raise HTTPException(503, "Unable to allocate a playback key")
        grant["index_key"] = index_key
        _node_playback_grants[short_key] = grant
        _node_playback_index[index_key] = short_key
        _schedule_node_playback_persist_locked()
        return short_key


def resolve_node_playback_key(playback_key: str, channel_ref: str, request: Request) -> tuple[NodeUserConfig, str, str]:
    now = time.time()
    grant: dict[str, Any] = {}
    if node_redis is not None and node_redis.available:
        try:
            grant = dict(node_redis.get_playback(playback_key) or {})
        except RuntimeError:
            grant = {}
    if not grant and NODE_MODE == "public" and NODE_PUBLIC_WORKER_COUNT > 1:
        raise HTTPException(503, "Node Redis runtime state is unavailable")
    if not grant:
        with _node_playback_key_lock:
            _cleanup_node_playback_keys(now)
            grant = dict(_node_playback_grants.get(playback_key) or {})
    if grant:
        if int(grant.get("exp") or 0) < int(now):
            raise HTTPException(403, "Playback key expired")
        if str(grant.get("ip") or "") != manager._client_ip(request):
            raise HTTPException(403, "Playback key is bound to another IP")
        user = require_panel_and_user(str(grant.get("user_token") or ""), request)
        granted_channel_key = str(grant.get("channel_key") or "")
        if granted_channel_key == "*":
            channel = next(
                (item for item in _effective_user_channels(user)
                 if str(channel_ref) in {item.key, str(_node_stream_id(item))}),
                None,
            )
        else:
            channel = next((item for item in _effective_user_channels(user) if item.key == granted_channel_key), None)
            if channel and str(channel_ref) not in {granted_channel_key, str(_node_stream_id(channel))}:
                channel = None
        if not channel:
            raise HTTPException(403, "Playback key does not match this channel")
        return user, str(grant.get("sid") or "")[:96], channel.key
    # Backward compatibility for playlist links created before v1.11.116.
    user = require_panel_and_user(playback_key, request)
    channel = next((item for item in _effective_user_channels(user) if item.key == channel_ref or str(_node_stream_id(item)) == str(channel_ref)), None)
    if not channel:
        raise HTTPException(404, "Stream not assigned to this user")
    return user, "", channel.key



@app.get("/channel-logos/{filename}")
def node_channel_logo(filename: str):
    safe = Path(filename).name
    if safe != filename or not safe.lower().endswith((".png", ".jpg", ".jpeg", ".webp")):
        raise HTTPException(404)
    path = CHANNEL_LOGO_ROOT / safe
    if not path.is_file():
        raise HTTPException(404)
    media = {".png": "image/png", ".jpg": "image/jpeg", ".jpeg": "image/jpeg", ".webp": "image/webp"}
    return FileResponse(path, media_type=media.get(path.suffix.lower(), "application/octet-stream"), headers={"Cache-Control": "public, max-age=86400"})


@app.get("/node-logos/{filename}")
def node_brand_logo(filename: str):
    safe = Path(filename).name
    if safe != filename or not safe.lower().endswith((".png", ".jpg", ".jpeg", ".webp", ".gif")):
        raise HTTPException(404)
    path = NODE_LOGO_ROOT / safe
    if not path.is_file():
        raise HTTPException(404)
    media = {".png": "image/png", ".jpg": "image/jpeg", ".jpeg": "image/jpeg", ".webp": "image/webp", ".gif": "image/gif"}
    return FileResponse(path, media_type=media.get(path.suffix.lower(), "application/octet-stream"), headers={"Cache-Control": "public, max-age=86400"})


