@app.get("/panel/login", response_class=HTMLResponse)
def node_panel_login_page(request: Request, error: str = ""):
    # STREAMFORGE_NODE_PANEL_LOGIN_BRANDING_V2288:
    if not manager.panel_connected(force=True):
        return _main_panel_disconnected_page(request, login_attempt=True)
    if _session_user(request):
        return RedirectResponse("/panel", status_code=303)
    error_html = f'<div class="error">{html.escape(error)}</div>' if error else ""
    matched_prefix = _CURRENT_PANEL_PREFIX.get()
    access_prefix = matched_prefix if matched_prefix is not None else (f"/{manager.access_slug}" if manager.access_slug else "")
    root_panel_alias = matched_prefix is not None and not access_prefix
    login_path = f"{access_prefix}/login" if access_prefix else "/login" if root_panel_alias else "/panel/login"
    logo_path = f"{access_prefix}/logo" if access_prefix else "/logo" if root_panel_alias else "/panel/logo"
    logo_html = (
        '<img class="login-brand-logo" src="' + html.escape(logo_path, quote=True) + '" alt="' + html.escape(manager.node_name) + ' logo">'
        if str(manager.node_logo_url or "").startswith("/node-logos/")
        else '<span class="login-brand-mark">' + html.escape((manager.node_name or "N")[:2].upper()) + '</span>'
    )
    canonical_path = access_prefix or "/"
    canonical_script = (
        '<script>/* STREAMFORGE_NODE_FIXED_LOGIN_ADDRESS_BAR_V3059 */'
        '(function(){const p=' + json.dumps(canonical_path) + ';'
        "window.STREAMFORGE_INTERNAL_PANEL_URL=location.pathname+location.search+location.hash;"
        "window.STREAMFORGE_FIXED_PANEL_ADDRESS_BAR=true;"
        "if(location.pathname!==p||location.search||location.hash)history.replaceState(history.state,'',p)})();</script>"
    )
    return HTMLResponse(
        '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">'
        + _node_favicon_link(access_prefix)
        + '<title>' + html.escape(manager.node_name or "Node") + '</title><style>'
        + 'body{margin:0;background:#0b0f14;color:#edf4fb;font:14px system-ui;display:grid;place-items:center;min-height:100vh}'
        + 'form{width:min(360px,90vw);background:#111821;border:1px solid #263243;border-radius:12px;padding:24px;display:grid;gap:12px}'
        + '.login-brand{display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;gap:10px;margin:0 0 6px}'
        + '.login-brand-logo,.login-brand-mark{width:72px;height:72px;border-radius:16px;background:#0b1118;border:1px solid #304156;object-fit:contain}'
        + '.login-brand-logo{padding:8px}.login-brand-mark{display:grid;place-items:center;font-size:20px;font-weight:800}'
        + '.login-brand h2{margin:0;font-size:24px;line-height:1.12}.login-brand p{margin:0;color:#8da0b5}'
        + 'input,button{padding:11px;border-radius:7px;border:1px solid #304156;background:#0b1118;color:#fff}'
        + 'button{background:#1d806a;cursor:pointer}.error{color:#ff9aa4}</style></head><body>'
        + '<form method="post" action="' + html.escape(login_path, quote=True) + '"><div class="login-brand">'
        + logo_html + '<h2>' + html.escape(manager.node_name or "Node") + '</h2></div>'
        + error_html
        + '<input name="username" placeholder="Username" required><input type="password" name="password" placeholder="Password" required><button>Sign in</button></form>'
        + canonical_script + '</body></html>'
    )


@app.post("/panel/login", response_class=HTMLResponse)
async def node_panel_login(request: Request):
    # STREAMFORGE_NODE_PANEL_LOGIN_ROLE_ISOLATION_V3057:
    # Panel authentication is independent of the browser Web Player login
    # mode. Never redirect a successful Panel/API login attempt to a
    # Playlist/App route when Web Player Auto Login is enabled.
    form = await request.form()
    username = str(form.get("username") or "").strip()
    password = str(form.get("password") or "")
    browser_ip = manager._client_ip(request)
    status, user, detail = manager.live_panel_authorize(
        username, action="login", password=password, client_ip=browser_ip
    )
    if status == "unavailable":
        # STREAMFORGE_ACCESS_LOG_CLIENT_IP_V73: Node Access log rows expose the browser IP directly.
        manager.log("Node panel login blocked because live Main authorization is unavailable", scope="auth", level="warning", details=f"ip={browser_ip}")
        return _main_panel_disconnected_page(request, login_attempt=True)
    if status != "ok" or not user:
        manager.log(f"Failed live node panel login for {username or 'unknown'}", scope="auth", level="warning", details=f"ip={browser_ip}")
        return node_panel_login_page(request, "Invalid username or password")
    manager.log(f"Live node panel login succeeded for {username}", scope="auth", details=f"ip={browser_ip}")
    response = RedirectResponse("/panel", status_code=303)
    _set_panel_session_cookie(response, request, _session_cookie(user.username, user.auth_version))
    # Always reset stale hidden-route state to Dashboard after a successful
    # login, otherwise Chrome can keep redispatching the visible root to login.
    _set_panel_route_cookie(response, request, "/panel")
    return response



