@app.post("/panel/account/password", response_class=HTMLResponse)
async def node_panel_account_password_change(request: Request):
    # STREAMFORGE_NODE_CHANGE_PASSWORD_ROUTE_V2255:
    user = require_node_panel_user(request, "")
    form = await request.form()
    current_password = str(form.get("current_password") or "")
    new_password = str(form.get("new_password") or "")
    confirm = str(form.get("new_password_confirm") or "")
    if len(new_password) < 8:
        return node_panel_account_password_page(request, error="New password must contain at least 8 characters.")
    if new_password != confirm:
        return node_panel_account_password_page(request, error="New password confirmation does not match.")
    status, updated_user, detail = manager.live_panel_authorize(
        user.username,
        action="change_password",
        password=current_password,
        auth_version=new_password,
        client_ip=manager._client_ip(request),
    )
    if status == "unavailable":
        return node_panel_account_password_page(request, error="Main Server is unavailable. Password was not changed.")
    if status != "ok" or not updated_user:
        return node_panel_account_password_page(request, error=detail or "Password change failed.")
    matched_prefix = _CURRENT_PANEL_PREFIX.get()
    access_prefix = matched_prefix if matched_prefix is not None else (f"/{manager.access_slug}" if manager.access_slug else "")
    target = (
        f"{access_prefix}/account/password?message={urllib.parse.quote_plus('Password changed successfully.')}"
        if access_prefix
        else "/panel/account/password?message=Password+changed+successfully."
    )
    response = RedirectResponse(target, status_code=303)
    _set_panel_session_cookie(response, request, _session_cookie(updated_user.username, updated_user.auth_version))
    return response


