@app.get("/panel/channels/{key}/errors.json")
def node_channel_errors_json(key: str, request: Request, page: int = 1, page_size: int = 10):
    user = require_node_panel_user(request, "channels.view")
    safe_key = manager.safe_key(key)
    with manager.lock:
        runtime = manager.channels.get(safe_key)
        raw_events = [dict(item) for item in manager.event_logs if str(item.get("channel") or "").strip() == safe_key]
    if not runtime:
        raise HTTPException(404, "Channel not found")
    status = manager.status(safe_key)
    events = _dedupe_node_channel_events(raw_events)
    status_name = str(status.get("status") or "").strip().lower()
    current_error = str(status.get("last_error") or "").strip() if status_name in {"error", "degraded", "starting", "restarting"} else ""
    safe_page_size = min(100, max(5, int(page_size or 10)))
    total = len(events) if events else (1 if current_error else 0)
    pages = max(1, (total + safe_page_size - 1) // safe_page_size)
    safe_page = min(max(1, int(page or 1)), pages)
    selected = events[(safe_page - 1) * safe_page_size:safe_page * safe_page_size]
    error_entries = [item for item in events if str(item.get("level") or "").lower() in {"warning", "error"}]
    restart_count = sum(
        1 for item in events
        if "restart" in str(item.get("message") or "").lower()
        or "ffmpeg exited" in str(item.get("message") or "").lower()
    )
    # This is the Node's runtime log, even when the channel configuration is
    # synchronized from Main.  Always attribute rows to the actual Node.
    server_name = manager.node_name or "Remote Node"
    # STREAMFORGE_NODE_MAIN_SHARED_LOG_SOURCE_HIDDEN_V87
    hide_source = str(runtime.config.catalog_owner or "main").strip().lower() == "main"
    source = "" if hide_source else _source_endpoint(runtime.config.input_url)
    if hide_source and current_error:
        current_error = re.sub(r"https?://[^\s]+", "[hidden Main source]", current_error)
    rows = []
    if current_error and not events:
        rows.append({
            "server_name": manager.node_name or "Remote Node",
            "source": "" if hide_source else _source_endpoint(runtime.config.input_url),
            "action": "ERROR",
            "action_class": "error",
            "level": "error",
            "message": "Current runtime error",
            "details": current_error,
            "created_at": _format_local_time(datetime.now(timezone.utc)),
        })
    for item in selected:
        action, action_class = _node_channel_log_action(item.get("message"), item.get("level"))
        details = str(item.get("details") or "").strip()
        if details:
            try:
                details = json.dumps(json.loads(details), ensure_ascii=False, sort_keys=True)
            except Exception:
                pass
            if hide_source:
                details = re.sub(r"https?://[^\s]+", "[hidden Main source]", details)
        rows.append({
            "server_name": server_name,
            "source": source,
            "action": action,
            "action_class": action_class,
            "level": str(item.get("level") or "info"),
            "message": str(item.get("message") or "Unknown event"),
            "details": details,
            "created_at": _format_local_time(item.get("time")),
        })
    return {
        "channel": safe_key,
        "channel_name": runtime.config.name,
        "current_error": current_error,
        "count": max(len(error_entries), 1 if current_error else 0),
        "restart_count": restart_count,
        "page": safe_page,
        "page_size": safe_page_size,
        "pages": pages,
        "total": total,
        "can_clear": _has_panel_permission(user, "logs.manage"),
        "hide_source": hide_source,
        # STREAMFORGE_NODE_CHANNEL_LOG_CLEAR_PUBLIC_PREFIX_V1140:
        # The Node Panel can intentionally live at the authority root (or any
        # configured path prefix).  The surrounding HTML is canonicalized from
        # internal /panel/... routes to that public prefix, but this JSON payload
        # is returned after document rendering and therefore must build its clear
        # endpoint explicitly.  Returning /panel/... on a root alias is rejected
        # by SilentInvalidNodeAccessMiddleware and Nginx surfaces that intentional
        # transport close as HTTP 502.
        "clear_endpoint": (
            f"{(_CURRENT_PANEL_PREFIX.get() or '')}/channels/"
            f"{urllib.parse.quote(safe_key, safe='')}/errors/clear"
        ),
        "entries": rows,
    }


@app.post("/panel/channels/{key}/errors/clear")
def node_channel_errors_clear(key: str, request: Request):
    require_node_panel_user(request, "logs.manage")
    safe_key = manager.safe_key(key)
    with manager.lock:
        runtime = manager.channels.get(safe_key)
        if not runtime:
            raise HTTPException(404, "Channel not found")
        previous = list(manager.event_logs)
        remaining = [item for item in previous if str(item.get("channel") or "").strip() != safe_key]
        cleared = len(previous) - len(remaining)
        manager.event_logs = deque(remaining, maxlen=NODE_EVENT_LOG_MAX)
        runtime.last_error = ""
    _rewrite_node_event_log_file()
    return {"ok": True, "cleared": cleared}


def _node_channel_delivery_status(config: ChannelConfig, status: dict[str, Any]) -> str:
    """Classify a Node channel by playable delivery, not process liveness."""
    runtime_status = str(status.get("status") or "unknown").strip().lower()
    if config.output_type == "hls" and bool(status.get("alive")) and bool(status.get("hls_ready")):
        return "up"
    if bool(status.get("desired_running")) or bool(status.get("alive")) or runtime_status in {
        "running", "starting", "restarting", "degraded",
    }:
        return "waiting"
    return "down"


@app.get("/panel/status.json")
def node_panel_status(request: Request):
    require_node_panel_user(request, "channels.view")
    # STREAMFORGE_NODE_PANEL_STATUS_NO_GEO_V1066:
    # Dashboard cards/rows need only viewer counts, never ASN/country details.
    # Avoid synchronous IPinfo lookups on the panel status hot path.
    viewer_stats = manager.viewer_stats(include_geo=False)
    channel_viewers = viewer_stats.get("channels", {})
    channels: dict[str, dict[str, Any]] = {}
    error_map = _node_recent_channel_errors()
    with manager.lock:
        channel_configs = {key: runtime.config for key, runtime in manager.channels.items()}
    for key, config in channel_configs.items():
        status = manager.status(key)
        status_name = str(status.get("status") or "unknown").strip().lower()
        delivery_status = _node_channel_delivery_status(config, status) if config else "down"
        runtime_error = str(status.get("last_error") or "").strip()
        current_error = runtime_error if status_name in {"error", "degraded", "starting", "restarting"} else ""
        channels[key] = {
            # STREAMFORGE_CHANNEL_STRICT_HLS_UP_WAITING_V3055:
            "status": delivery_status,
            "runtime_status": status_name,
            "desired_running": bool(status.get("desired_running")),
            "alive": bool(status.get("alive")),
            "hls_ready": bool(status.get("hls_ready")),
            "online_users": int(channel_viewers.get(key, 0) or 0),
            "bitrate_kbps": int(status.get("bitrate_kbps") or 0),
            "speed_x": float(status.get("speed_x") or 0.0),
            "resolution": str(status.get("resolution") or "Source"),
            "fps": float(status.get("fps") or 0.0),
            "last_error": current_error,
            "error_count": max(len(error_map.get(key, [])), 1 if current_error else 0),
            "restart_count": sum(1 for item in error_map.get(key, []) if "restart" in str(item.get("message") or "").lower() or "ffmpeg exited" in str(item.get("message") or "").lower()),
            "uptime_seconds": int(status.get("uptime_seconds") or 0),
            "waiting_seconds": int(status.get("waiting_seconds") or 0),
        }
    return {
        "ok": True,
        "online_users": int(viewer_stats.get("total_users", 0) or 0),
        # STREAMFORGE_NODE_DASHBOARD_ACTIVE_NO_FLASH_V94: keep the card on
        # the same playable-up state used by dashboard rows.
        "active_channels": sum(1 for item in channels.values() if item["status"] == "up"),
        "active_connections": int(manager.total_active_connections()),
        "total_max_connections": int(manager.total_max_connections),
        "metrics": manager.metrics(),
        "channels": channels,
    }



