def _node_user_xtream_url_with_credentials(user: NodeUserConfig, username: str, password: str = "", user_type: str | None = None) -> str:
    """Rebuild a Node-local Xtream URL while retaining an unchanged password safely."""
    saved = manager.current_xtream_output_url(user) or str(user.xtream_output_url or "").strip()
    base = manager.stream_output_base()
    try:
        parsed = urllib.parse.urlsplit(saved) if saved else None
        pairs = urllib.parse.parse_qsl(parsed.query, keep_blank_values=True) if parsed else []
    except ValueError:
        pairs = []
    existing_password = next((value for key, value in pairs if key == "password"), "")
    effective_password = password if password else existing_password
    if not effective_password:
        if username.lower() != str(user.username or "").strip().lower():
            raise ValueError("Enter a new password when changing this username because the saved Xtream password is unavailable")
        return saved
    remaining = [(key, value) for key, value in pairs if key not in {"username", "password"}]
    if not any(key == "type" for key, _value in remaining):
        remaining.append(("type", "m3u_plus"))
    remaining = [(key, value) for key, value in remaining if key != "output"]
    effective_type = "restream" if str(user_type or user.user_type or "viewer").lower() == "restream" else "viewer"
    remaining.append(("output", "ts" if effective_type == "restream" else "m3u8"))
    query = [("username", username), ("password", effective_password), *remaining]
    if base:
        return f"{base}/get.php?{urllib.parse.urlencode(query)}"
    if parsed and parsed.scheme and parsed.netloc:
        path_base = parsed.path.rsplit("/", 1)[0].rstrip("/")
        return urllib.parse.urlunsplit((parsed.scheme, parsed.netloc, f"{path_base}/get.php", urllib.parse.urlencode(query), ""))
    return saved


@app.get("/panel/users/{token}/edit", response_class=HTMLResponse)
def node_panel_stream_user_edit(token: str, request: Request):
    user = require_node_panel_user(request, "stream_users.edit")
    with manager.lock:
        target = manager.users.get(token)
    if not target:
        raise HTTPException(404, "Playlist user not found")
    if str(target.source or "").strip().lower() != "node_local":
        raise HTTPException(409, "Main-synchronized users are read-only")
    return HTMLResponse(_panel_stream_user_form(user, target=target))


@app.post("/panel/users/{token}/edit", response_class=HTMLResponse)
async def node_panel_stream_user_edit_save(token: str, request: Request):
    actor = require_node_panel_user(request, "stream_users.edit")
    with manager.lock:
        target = manager.users.get(token)
    if not target:
        raise HTTPException(404, "Playlist user not found")
    if str(target.source or "").strip().lower() != "node_local":
        raise HTTPException(409, "Main-synchronized users are read-only")
    form = await request.form()
    submitted_username = str(form.get("username") or "").strip()
    submitted_password = str(form.get("password") or "")
    # STREAMFORGE_NODE_PLAYLIST_USER_EDIT_DISPLAY_NAME_V1042:
    submitted_name = str(form.get("name") or "").strip()
    try:
        if not re.fullmatch(r"[A-Za-z0-9._-]{1,120}", submitted_username):
            raise ValueError("Username may contain letters, numbers, dot, underscore and dash only")
        if submitted_password and len(submitted_password) < 4:
            raise ValueError("New password must contain at least 4 characters")
        account_type = "restream" if str(form.get("user_type") or target.user_type or "viewer").lower() == "restream" else "viewer"
        normalized_restream_ips = _normalize_node_restream_rules(form.get("restream_allowed_ips")) if account_type == "restream" else ""
        if account_type == "restream" and not normalized_restream_ips:
            raise ValueError("Restreamer accounts require at least one allowed IP or CIDR")
        with manager.lock:
            if any(
                other_token != token and str(item.username or "").strip().lower() == submitted_username.lower()
                for other_token, item in manager.users.items()
            ):
                raise ValueError("Username already exists on this node")
        effective_display_name = submitted_name or submitted_username
        # STREAMFORGE_NODE_PLAYLIST_USER_EDIT_EXPIRY_V129:
        # Blank means Never; datetime-local values are interpreted as UTC to
        # match the label and the Node's existing create-user behavior.
        submitted_expiry_raw = str(form.get("expires_at") or "").strip()
        submitted_expires_at = None
        if submitted_expiry_raw:
            parsed_submitted_expiry = datetime.fromisoformat(submitted_expiry_raw.replace("Z", "+00:00"))
            if parsed_submitted_expiry.tzinfo is None:
                parsed_submitted_expiry = parsed_submitted_expiry.replace(tzinfo=timezone.utc)
            submitted_expires_at = parsed_submitted_expiry.astimezone(timezone.utc).isoformat()
        playlist_selection = _resolve_node_user_playlist_selection(
            form.get("playlist_id"),
            [str(value) for value in form.getlist("channel_ids")],
            str(effective_display_name or "Playlist user"),
            existing=target,
        )
        credentials_changed = False
        with manager.lock:
            current = manager.users.get(token)
            if not current:
                raise ValueError("Playlist user no longer exists")
            credentials_changed = (submitted_username.lower() != str(current.username or "").strip().lower()) or bool(submitted_password)
            updated_xtream_url = _node_user_xtream_url_with_credentials(current, submitted_username, submitted_password, account_type)
            current.username = submitted_username
            current.name = effective_display_name
            if submitted_password:
                current.password_hash = hash_scrypt_password(submitted_password)
            current.user_type = account_type
            current.restream_allowed_ips = normalized_restream_ips
            # STREAMFORGE_NODE_PLAYLIST_USER_EDIT_MAX_V2245:
            raw_max_connections = form.get("max_connections")
            current.max_connections = max(
                0, min(100, int(current.max_connections if raw_max_connections in (None, "") else raw_max_connections))
            )
            current.expires_at = submitted_expires_at
            current.xtream_output_url = updated_xtream_url
            current.playlist_name = str(playlist_selection["playlist_name"])
            current.playlist_logo_url = str(playlist_selection["playlist_logo_url"])
            current.playlist_profile_id = str(playlist_selection["playlist_profile_id"])
            current.all_node_channels = bool(playlist_selection["all_node_channels"])
            current.channels = list(playlist_selection["channels"])
            current.playlist_order = list(playlist_selection["playlist_order"])
            current.playlist_category_order = list(playlist_selection["playlist_category_order"])
            if credentials_changed:
                for key in [key for key in manager.viewer_sessions if key[0] == token]:
                    manager.viewer_sessions.pop(key, None)
                for key in [key for key in manager.connection_reservations if key[0] == token]:
                    manager.connection_reservations.pop(key, None)
                manager._save_shared_viewers()
            manager.save_users()
    except (RuntimeError, ValueError, TypeError) as exc:
        draft = target.model_copy(update={
            "username": submitted_username or target.username,
            "name": submitted_name or submitted_username or target.name or target.username,
            "user_type": "restream" if str(form.get("user_type") or target.user_type or "viewer").lower() == "restream" else "viewer",
            "restream_allowed_ips": str(form.get("restream_allowed_ips") or target.restream_allowed_ips or ""),
            "expires_at": str(form.get("expires_at") or "").strip() or None,
        })
        return HTMLResponse(_panel_stream_user_form(actor, str(exc), draft), status_code=400)
    manager.log(
        "Node-local playlist user credentials and playlist updated",
        scope="user",
        details=f"{submitted_username} by {actor.username}",
    )
    return RedirectResponse(
        "/panel/users?message=" + urllib.parse.quote_plus("Playlist user updated"),
        status_code=303,
    )


@app.post("/panel/users/{token}/delete")
def node_panel_stream_user_delete(token: str, request: Request):
    actor = require_node_panel_user(request, "stream_users.delete")
    with manager.lock:
        target = manager.users.get(token)
        if not target:
            raise HTTPException(404, "Playlist user not found")
        if str(target.source or "").strip().lower() != "node_local":
            raise HTTPException(409, "Main-synchronized users are read-only")
        deleted_name = str(target.name or target.username or "Playlist user")
        deleted_username = str(target.username or "")
        manager.users.pop(token, None)
        for key in [key for key in manager.viewer_sessions if key[0] == token]:
            manager.viewer_sessions.pop(key, None)
        for key in [key for key in manager.connection_reservations if key[0] == token]:
            manager.connection_reservations.pop(key, None)
        manager._save_shared_viewers()
        manager.save_users()
    manager.log(
        "Node-local playlist user deleted", scope="user",
        details=f"{deleted_name} ({deleted_username}) by {actor.username}" if deleted_username else f"{deleted_name} by {actor.username}",
    )
    return RedirectResponse(
        "/panel/users?message=" + urllib.parse.quote_plus("Playlist user deleted"),
        status_code=303,
    )


