@app.post("/panel/users/{token}/order", response_class=HTMLResponse)
async def node_panel_playlist_order_save(token: str, request: Request):
    user = require_node_panel_user(request, "stream_users.edit")
    with manager.lock:
        target = manager.users.get(token)
    if not target:
        raise HTTPException(404, "Playlist user not found")
    if target.source != "node_local":
        raise HTTPException(409, "Main-synchronized users are read-only; create a Node-local playlist user")
    form = await request.form()
    try:
        parsed = json.loads(str(form.get("playlist_order") or "[]"))
        parsed_categories = json.loads(str(form.get("playlist_category_order") or "[]"))
        if not isinstance(parsed, list) or not isinstance(parsed_categories, list):
            raise ValueError("Invalid playlist hierarchy")
        effective = _effective_user_channels(target)
        available = {item.key for item in effective}
        available_categories = {(item.category or "Uncategorized").strip().lower() or "uncategorized" for item in effective}
        category_order: list[str] = []
        for item in parsed_categories:
            category_key = str(item or "").strip().lower()
            if category_key in available_categories and category_key not in category_order:
                category_order.append(category_key)
        fallback_categories = sorted(
            available_categories,
            key=lambda value: _category_sort_value(next((item.category for item in effective if (item.category or "Uncategorized").strip().lower() == value), value)),
        )
        category_order.extend(value for value in fallback_categories if value not in category_order)
        order: list[str] = []
        for item in parsed:
            key = str(item or "").strip()
            if key in available and key not in order:
                order.append(key)
        order.extend(item.key for item in _effective_user_channels(target) if item.key not in order)
        with manager.lock:
            current = manager.users.get(token)
            if not current:
                raise ValueError("Playlist user no longer exists")
            current.playlist_order = order
            current.playlist_category_order = category_order
            manager.save_users()
        manager.log("Node-local playlist category/channel order updated", scope="user", details=target.username or target.name)
    except (ValueError, TypeError, json.JSONDecodeError) as exc:
        return HTMLResponse(_panel_playlist_order_page(user, target, str(exc)), status_code=400)
    return RedirectResponse("/panel/users?message=" + urllib.parse.quote_plus("Node playlist category and channel order saved"), status_code=303)


