@app.post("/panel/playlists/{token}/order", response_class=HTMLResponse)
async def node_panel_profile_order_save(token: str, request: Request):
    user = require_node_panel_user(request, "stream_users.edit")
    with manager.lock:
        profile = manager.playlists.get(token)
    if not profile:
        raise HTTPException(404, "Playlist not found")
    form = await request.form()
    try:
        parsed = json.loads(str(form.get("playlist_order") or "[]"))
        parsed_categories = json.loads(str(form.get("playlist_category_order") or "[]"))
        if not isinstance(parsed, list) or not isinstance(parsed_categories, list):
            raise ValueError("Invalid playlist hierarchy")
        effective = _effective_profile_channels(profile)
        available = {item.key for item in effective}
        available_categories = {(item.category or "Uncategorized").strip().lower() or "uncategorized" for item in effective}
        category_order: list[str] = []
        for item in parsed_categories:
            category_key = str(item or "").strip().lower()
            if category_key in available_categories and category_key not in category_order:
                category_order.append(category_key)
        for name in _effective_category_order_names():
            key = name.lower()
            if key in available_categories and key not in category_order:
                category_order.append(key)
        order: list[str] = []
        for item in parsed:
            key = str(item or "").strip()
            if key in available and key not in order:
                order.append(key)
        order.extend(item.key for item in effective if item.key not in order)
        with manager.lock:
            current = manager.playlists.get(token)
            if not current:
                raise ValueError("Playlist no longer exists")
            current.playlist_order = order
            current.playlist_category_order = category_order
            manager.save_users()
        manager.log("Node-local playlist category/channel order updated", scope="user", details=profile.name)
    except (ValueError, TypeError, json.JSONDecodeError) as exc:
        return HTMLResponse(_panel_playlist_order_page(user, profile, str(exc), profile_mode=True), status_code=400)
    return RedirectResponse("/panel/playlists?message=" + urllib.parse.quote_plus("Playlist category and channel order saved"), status_code=303)


