@app.get("/panel/sessions.json")
def node_panel_sessions_json(request: Request, channel: str = "", user: str = ""):
    # STREAMFORGE_NODE_LIVE_SESSIONS_JSON_V2286:
    panel_user = require_node_panel_user(request, "channels.view")
    stats = manager.viewer_stats()
    selected_channel = str(channel or "").strip()
    selected_user = str(user or "").strip()
    all_sessions = list(stats.get("sessions") or [])
    sessions = [
        item for item in all_sessions
        if (not selected_channel or str(item.get("channel_key") or "") == selected_channel)
        and (not selected_user or str(item.get("user_name") or "Unknown user") == selected_user)
    ]
    can_kill = _has_panel_permission(panel_user, "stream_users.kill")
    payload = []
    for item in sessions:
        source = str(item.get("source") or "Unknown")
        source_key = str(item.get("source_key") or ("direct_node" if source.lower().startswith("direct") else "main_proxy"))
        payload.append({
            "user_name": str(item.get("user_name") or "Unknown user"),
            "session_id": str(item.get("session_id") or ""),
            "client_ip": str(item.get("client_ip") or "unknown"),
            "business_name": str(item.get("business_name") or "Unknown network"),
            "asn": item.get("asn"),
            "country_name": str(item.get("country_name") or "Unknown"),
            "country_code": str(item.get("country_code") or ""),
            "channel_key": str(item.get("channel_key") or ""),
            "channel_name": str(item.get("channel_name") or item.get("channel_key") or "Unknown"),
            "source": source,
            "source_key": source_key,
            "duration_text": _human_duration(item.get("duration_seconds")),
            "idle_text": _human_duration(item.get("idle_seconds")),
            "last_seen_text": _format_local_time(item.get("last_seen_at")),
            "user_agent": str(item.get("user_agent") or "Unknown client"),
            "user_id": item.get("user_id") or "",
            "can_kill": bool(can_kill),
        })
    response = JSONResponse({
        "ok": True,
        "sessions": payload,
        "filtered_count": len(payload),
        "online_users": int(stats.get("total_users") or 0),
        "unique_accounts": int(stats.get("unique_accounts") or 0),
        "online_user_names": sorted({str(item.get("user_name") or "Unknown user") for item in all_sessions}, key=str.lower),
    })
    response.headers["Cache-Control"] = "no-store, no-cache, must-revalidate, max-age=0"
    response.headers["Pragma"] = "no-cache"
    return response


@app.get("/panel/metrics-history.json")
def node_panel_metrics_history(request: Request, span_hours: int = 0):
    require_node_panel_user(request, "channels.view")
    days = max(1, min(3650, int(_node_operations_settings().get("metrics_retention_days") or 30)))
    default_hours = max(1, min(days * 24, int(_node_operations_settings().get("metrics_default_span_hours") or 24)))
    selected_hours = max(1, min(days * 24, int(span_hours or default_hours)))
    cutoff = int(time.time()) - selected_hours * 3600
    points = [item for item in _node_metrics_rows(1_000_000) if int(item.get("time") or 0) >= cutoff]
    if len(points) > 1440:
        step = max(1, (len(points) + 1439) // 1440)
        points = points[::step][-1440:]
    return {"retention_days": days, "default_span_hours": default_hours, "span_hours": selected_hours, "points": points}


# STREAMFORGE_NODE_PANEL_HLS_PREVIEW_V1070:
# The Channels H button opens a real browser player rather than a raw .m3u8.
# Media uses a random, IP-bound, sliding short-idle grant so HLS segment requests
# do not perform Main live panel authorization on every fragment.
_PANEL_PLAY_GRANT_IDLE_SECONDS = max(30, min(600, int(os.getenv("STREAMFORGE_NODE_PANEL_PLAY_GRANT_IDLE_SECONDS", "120"))))
_panel_play_grant_lock = threading.RLock()
_panel_play_grants: dict[str, dict[str, Any]] = {}


def _cleanup_panel_play_grants_locked(now: float) -> None:
    if len(_panel_play_grants) <= 4096:
        stale = [token for token, item in _panel_play_grants.items() if float(item.get("expires") or 0.0) <= now]
    else:
        stale = sorted(
            _panel_play_grants,
            key=lambda token: float(_panel_play_grants[token].get("expires") or 0.0),
        )[: max(256, len(_panel_play_grants) - 4096)]
        stale.extend(
            token for token, item in _panel_play_grants.items()
            if float(item.get("expires") or 0.0) <= now and token not in stale
        )
    for token in stale:
        _panel_play_grants.pop(token, None)


def _issue_panel_play_grant(key: str, request: Request) -> str:
    safe_key = manager.safe_key(key)
    now = time.monotonic()
    token = secrets.token_urlsafe(24).rstrip("=")
    with _panel_play_grant_lock:
        _cleanup_panel_play_grants_locked(now)
        _panel_play_grants[token] = {
            "key": safe_key,
            "ip": manager._client_ip(request),
            "expires": now + _PANEL_PLAY_GRANT_IDLE_SECONDS,
        }
    return token


def _panel_play_grant_valid(key: str, request: Request, grant: str) -> bool:
    token = str(grant or "").strip()
    if not re.fullmatch(r"[A-Za-z0-9_-]{20,80}", token):
        return False
    safe_key = manager.safe_key(key)
    now = time.monotonic()
    ip_text = manager._client_ip(request)
    with _panel_play_grant_lock:
        item = _panel_play_grants.get(token)
        if not item:
            return False
        if float(item.get("expires") or 0.0) <= now:
            _panel_play_grants.pop(token, None)
            return False
        if str(item.get("key") or "") != safe_key or str(item.get("ip") or "") != ip_text:
            return False
        # Sliding inactivity TTL: an actively playing stream remains valid, while
        # a copied/abandoned preview token expires quickly when media traffic stops.
        item["expires"] = now + _PANEL_PLAY_GRANT_IDLE_SECONDS
        return True


def _panel_play_authorize(key: str, request: Request, grant: str) -> str:
    if _panel_play_grant_valid(key, request, grant):
        return str(grant)
    # Backward compatibility for an old/raw panel-play URL. Authenticate once,
    # then upgrade the returned manifest to the short-lived local media grant.
    require_node_panel_user(request, "channels.view")
    return _issue_panel_play_grant(key, request)


@app.get("/panel/channels/{key}/play", response_class=HTMLResponse)
def node_panel_channel_play(key: str, request: Request):
    # STREAMFORGE_NODE_HLS_VIDEO_ONLY_V1076:
    # The Channels H action is a preview, not another Panel screen. Return a
    # bare browser video surface with only native video controls; no sidebar,
    # toolbar, status badge, metrics or navigation options.
    require_node_panel_user(request, "channels.view")
    safe_key = manager.safe_key(key)
    with manager.lock:
        runtime = manager.channels.get(safe_key)
        config = runtime.config if runtime else None
    if not config:
        raise HTTPException(404, "Channel not found")
    if config.output_type != "hls":
        raise HTTPException(400, "This channel does not use HLS output")

    grant = _issue_panel_play_grant(safe_key, request)
    escaped_key = urllib.parse.quote(safe_key, safe="")
    matched_prefix = _CURRENT_PANEL_PREFIX.get()
    access_prefix = matched_prefix if matched_prefix is not None else (f"/{manager.access_slug}" if manager.access_slug else "")
    media_prefix = access_prefix.rstrip("/")
    source_url = f"{media_prefix}/panel-play/{escaped_key}/master.m3u8?grant={urllib.parse.quote(grant, safe='')}"
    source_json = json.dumps(source_url)
    title_text = html.escape(config.name or safe_key)
    return HTMLResponse(f'''<!doctype html>
<html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<title>{title_text}</title>
<style>
html,body{{width:100%;height:100%;margin:0;background:#000;overflow:hidden}}
body{{display:grid;place-items:center}}
video{{display:block;width:100vw;height:100vh;background:#000;object-fit:contain}}
</style></head><body>
<video id="video" controls autoplay muted playsinline></video>
<script>
(()=>{{
  const video=document.getElementById('video'),source={source_json};
  let h=null,retryTimer=null,fatalCount=0;
  const destroy=()=>{{if(h){{try{{h.destroy()}}catch(_e){{}}h=null;}}}};
  const retry=()=>{{destroy();if(retryTimer!==null)return;retryTimer=setTimeout(()=>{{retryTimer=null;start();}},2500);}};
  const nativeStart=()=>{{destroy();video.src=source;video.load();video.play().catch(()=>{{}});}};
  const hlsStart=()=>{{destroy();h=new Hls({{enableWorker:true,lowLatencyMode:false,liveSyncDurationCount:2,liveMaxLatencyDurationCount:5,backBufferLength:15,maxBufferLength:10,maxMaxBufferLength:18,manifestLoadingTimeOut:10000,manifestLoadingMaxRetry:2,levelLoadingTimeOut:10000,levelLoadingMaxRetry:2,fragLoadingTimeOut:15000,fragLoadingMaxRetry:3}});h.attachMedia(video);h.on(Hls.Events.MEDIA_ATTACHED,()=>h.loadSource(source));h.on(Hls.Events.MANIFEST_PARSED,()=>{{fatalCount=0;video.play().catch(()=>{{}});}});h.on(Hls.Events.ERROR,(_event,data)=>{{if(!data||!data.fatal)return;fatalCount+=1;if(data.type===Hls.ErrorTypes.NETWORK_ERROR&&fatalCount<=2){{try{{h.startLoad();return;}}catch(_e){{}}}}if(data.type===Hls.ErrorTypes.MEDIA_ERROR&&fatalCount<=2){{try{{h.recoverMediaError();return;}}catch(_e){{}}}}retry();}});}};
  function start(){{fatalCount=0;if(video.canPlayType('application/vnd.apple.mpegurl')){{nativeStart();return;}}if(window.Hls&&Hls.isSupported()){{hlsStart();return;}}retry();}}
  video.addEventListener('error',retry);
  const script=document.createElement('script');script.src='https://cdn.jsdelivr.net/npm/hls.js@1.7.1/dist/hls.min.js';script.onload=start;script.onerror=start;document.head.appendChild(script);
  window.addEventListener('beforeunload',()=>{{destroy();if(retryTimer!==null)clearTimeout(retryTimer);}});
}})();
</script></body></html>''', headers={"Cache-Control": "no-store"})


@app.get("/panel-play/{key}/master.m3u8", response_class=PlainTextResponse)
def panel_http_master(key: str, request: Request, grant: str = ""):
    safe_key = manager.safe_key(key)
    media_grant = _panel_play_authorize(safe_key, request, grant)
    status = manager.status(safe_key)
    if not status.get("hls_ready"):
        raise HTTPException(503, "Stream is not ready")
    grant_query = urllib.parse.quote(media_grant, safe="")
    return PlainTextResponse(
        f"#EXTM3U\n#EXT-X-VERSION:3\n#EXT-X-STREAM-INF:BANDWIDTH=3000000\nindex.m3u8?grant={grant_query}\n",
        media_type="application/vnd.apple.mpegurl",
        headers={"Cache-Control": "no-store", "Access-Control-Allow-Origin": "*", "X-StreamForge-Panel-Media-Grant": "sliding"},
    )


@app.get("/panel-play/{key}/index.m3u8", response_class=PlainTextResponse)
def panel_http_playlist(key: str, request: Request, grant: str = ""):
    safe_key = manager.safe_key(key)
    media_grant = _panel_play_authorize(safe_key, request, grant)
    path = HLS_ROOT / safe_key / "index.m3u8"
    if not path.is_file():
        raise HTTPException(503, "Stream is not ready")
    grant_query = urllib.parse.quote(media_grant, safe="")
    lines = [
        f"{urllib.parse.quote(Path(line).name, safe='')}?grant={grant_query}"
        if line and not line.startswith("#") else line
        for line in path.read_text(errors="replace").splitlines()
    ]
    return PlainTextResponse(
        "\n".join(lines) + "\n",
        media_type="application/vnd.apple.mpegurl",
        headers={"Cache-Control": "no-store", "Access-Control-Allow-Origin": "*", "X-StreamForge-Panel-Media-Grant": "sliding"},
    )


@app.get("/panel-play/{key}/{filename}")
def panel_http_segment(key: str, filename: str, request: Request, grant: str = ""):
    safe_key = manager.safe_key(key)
    _panel_play_authorize(safe_key, request, grant)
    safe = Path(filename).name
    if safe != filename or not safe.endswith((".ts", ".m4s", ".aac", ".mp3", ".key")):
        raise HTTPException(404)
    path = HLS_ROOT / safe_key / safe
    if not path.is_file():
        raise HTTPException(404)
    media = {".ts": "video/mp2t", ".m4s": "video/iso.segment", ".aac": "audio/aac", ".mp3": "audio/mpeg", ".key": "application/octet-stream"}
    return FileResponse(
        path,
        media_type=media.get(path.suffix.lower(), "application/octet-stream"),
        headers={"Cache-Control": "no-store", "Access-Control-Allow-Origin": "*", "X-StreamForge-Panel-Media-Grant": "sliding"},
    )


def _node_panel_action(request: Request, key: str, action: str, permission: str):
    require_node_panel_user(request, permission)
    manager.safe_key(key)
    manager.reload_channel_catalog_if_changed()
    with manager.lock:
        runtime = manager.channels.get(key)
    if not runtime:
        raise HTTPException(404, "Channel not found")
    if action == "start":
        manager.start(key, runtime.config)
    elif action == "stop":
        manager.stop(key)
    else:
        manager.restart(key, runtime.config)
    manager.log(f"Panel user requested channel {action}", scope="channel", key=key)
    # STREAMFORGE_NODE_CHANNEL_ACTION_AJAX_V2250:
    if request.headers.get("X-StreamForge-Ajax") == "1":
        return JSONResponse({"ok": True, "action": action, "key": key})
    message = urllib.parse.quote_plus(action.title() + " command sent")
    return RedirectResponse(f"/panel/manage/channels?message={message}", status_code=303)


@app.post("/panel/channels/{key}/start")
def node_panel_start(key: str, request: Request):
    return _node_panel_action(request, key, "start", "channels.start")


@app.post("/panel/channels/{key}/stop")
def node_panel_stop(key: str, request: Request):
    return _node_panel_action(request, key, "stop", "channels.stop")


@app.post("/panel/channels/{key}/restart")
def node_panel_restart(key: str, request: Request):
    return _node_panel_action(request, key, "restart", "channels.restart")


# STREAMFORGE_NODE_PASSWORD_SIGNOUT_FOOTER_V2281
def _node_panel_nav_items(user: PanelAccessUser) -> list[tuple[str, str, str]]:
    items: list[tuple[str, str, str]] = [("dashboard", "Dashboard", "/panel")]
    if _has_panel_permission(user, "channels.view"):
        items.append(("channels", "Channels", "/panel/manage/channels"))
        items.append(("sessions", "Live sessions", "/panel/sessions"))
    if _has_panel_permission(user, "categories.view"):
        items.append(("categories", "Categories", "/panel/manage/categories"))
    if _has_panel_permission(user, "stream_users.view"):
        items.append(("playlists", "Playlists", "/panel/playlists"))
        items.append(("users", "Playlist users", "/panel/users"))
    if _has_panel_permission(user, "logs.view"):
        items.append(("logs", "Logs", "/panel/manage/logs"))
    if _has_panel_permission(user, "nodes.edit"):
        items.append(("settings", "Settings", "/panel/manage/settings"))
    return items


def _node_panel_header(user: PanelAccessUser, active: str = "") -> str:
    logo_url = manager.node_logo_url
    if logo_url.startswith("/node-logos/"):
        matched_prefix = _CURRENT_PANEL_PREFIX.get()
        access_prefix = matched_prefix if matched_prefix is not None else (f"/{manager.access_slug}" if manager.access_slug else "")
        logo_url = f"{access_prefix}{logo_url}"
    logo = (
        f'<img class="panel-logo" src="{html.escape(logo_url, quote=True)}" alt="">'
        if logo_url
        else '<span class="panel-mark">SF</span>'
    )
    nav_icons = {
        "dashboard": '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 13h6V4H4v9Zm10 7h6V11h-6v9ZM4 20h6v-3H4v3Zm10-13h6V4h-6v3Z"/></svg>',
        "channels": '<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="4" y="5" width="16" height="14" rx="2"/><path d="M9 5v14M15 5v14"/></svg>',
        "sessions": '<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="8" cy="12" r="3"/><path d="M13 7c2 1 3 2.7 3 5s-1 4-3 5M16 4c3.4 1.8 5 4.5 5 8s-1.6 6.2-5 8"/></svg>',
        "categories": '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 5h6v6H4zM14 5h6v6h-6zM4 15h6v4H4zM14 15h6v4h-6z"/></svg>',
        "playlists": '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 6h10M5 10h10M5 14h7"/><path d="m15 14 4 3-4 3z"/></svg>',
        "users": '<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="9" cy="8" r="3"/><path d="M4 19c0-3 2.2-5 5-5s5 2 5 5M16 7h4M18 5v4"/></svg>',
        "logs": '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 5h12M6 9h12M6 13h12M6 17h8"/></svg>',
        "settings": '<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="3"/><path d="M19 12a7 7 0 0 0-.1-1l2-1.5-2-3.4-2.4 1A8 8 0 0 0 15 6l-.3-2.6h-4L10.4 6A8 8 0 0 0 8.8 7L6.4 6 4.5 9.5 6.5 11a7 7 0 0 0 0 2l-2 1.5L6.4 18l2.4-1a8 8 0 0 0 1.6 1l.3 2.6h4L15 18a8 8 0 0 0 1.6-1l2.4 1 2-3.5-2.1-1.5c.1-.3.1-.7.1-1Z"/></svg>',
        "account": '<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="5" y="10" width="14" height="10" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/><circle cx="12" cy="15" r="1.4"/><path d="M12 16.4V18"/></svg>',
    }
    links = []
    for key, label, url in _node_panel_nav_items(user):
        active_class = " active" if key == active else ""
        current = ' aria-current="page"' if key == active else ""
        icon = nav_icons.get(key, "")
        links.append(
            f'<a class="nav-button{active_class}" href="{url}"{current}>'
            f'<span class="node-nav-icon">{icon}</span>'
            f'<span class="node-nav-label">{html.escape(label)}</span>'
            f'</a>'
        )
    mode = "Independent" if manager.independent_mode else "Shared"
    return f'''<header class="panel-header">
<div class="panel-brand-row">
  <div class="panel-brand">{logo}<div><b>{html.escape(manager.node_name)}</b><small>{mode} mode · v{html.escape(VERSION)}</small></div></div>
  <button class="panel-nav-toggle" type="button" aria-label="Collapse sidebar" aria-expanded="true" data-node-nav-toggle><span class="toggle-chevron" aria-hidden="true"></span><span class="toggle-line"></span><span class="toggle-line"></span><span class="toggle-line"></span></button>
</div>
<nav class="panel-nav" aria-label="Node panel navigation" data-node-nav>
  <div class="panel-nav-links">{''.join(links)}</div>
  <div class="panel-sidebar-footer">
    <span class="panel-user">{html.escape(user.username)}</span>
    <a class="nav-button account" href="/panel/account/password"><span class="node-nav-icon" aria-hidden="true">{nav_icons["account"]}</span><span class="node-nav-label">Change password</span></a>
    <a class="nav-button signout" href="/panel/logout"><span class="node-signout-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M10 4H6.8A1.8 1.8 0 0 0 5 5.8v12.4A1.8 1.8 0 0 0 6.8 20H10"/><path d="M14 8l4 4-4 4"/><path d="M9 12h9"/></svg></span><span class="node-signout-label">Sign out</span></a>
  </div>
</nav>
</header>'''


