def independent_channel_edit(key: str, request: Request):
    user = require_local_catalogue_user(request, 'channels.edit')
    rt = _local_channel_runtime(key)
    return HTMLResponse(_local_channel_form(user, rt.config))


@app.post('/panel/manage/channels/{key}/edit', response_class=HTMLResponse)
async def independent_channel_save(key: str, request: Request):
    user = require_local_catalogue_user(request, 'channels.edit')
    rt = _local_channel_runtime(key)
    form = await request.form()
    try:
        cfg = _channel_from_form(form, rt.config)
        cfg.key = key
        with manager.lock:
            if any(other_key != key and other.config.catalog_owner == 'local' and other.config.slug == cfg.slug for other_key, other in manager.channels.items()):
                raise ValueError('Channel slug already exists')
        cfg.logo_url = await _resolve_local_channel_logo(request, form, cfg.slug, rt.config.logo_url or '')
        result = manager.sync_channel(key, cfg, restart_running=False)
        if bool(result.get('restart_required')):
            threading.Thread(
                target=_restart_node_channel_after_save,
                args=(key, cfg.model_copy(deep=True)),
                daemon=True,
                name=f'sf-node-save-restart-{key[:24]}',
            ).start()
        manager.log('Node-local channel updated', scope='channel', key=key)
        return RedirectResponse('/panel/manage/channels?message=' + urllib.parse.quote_plus('Channel updated'), 303)
    except (ValueError, TypeError) as exc:
        return HTMLResponse(_local_channel_form(user, rt.config, str(exc)), 400)


