# STREAMFORGE_NODE_PANEL_LOGIN_LOGO_ROUTE_V2288:
@app.get("/panel/logo")
def node_panel_logo():
    _node_name, logo = _node_identity_snapshot()
    if not logo.startswith("/node-logos/"):
        raise HTTPException(404)
    filename = Path(logo[len("/node-logos/"):]).name
    if not filename or filename != logo[len("/node-logos/"):]:
        raise HTTPException(404)
    path = NODE_LOGO_ROOT / filename
    if not path.is_file():
        raise HTTPException(404)
    media={".png":"image/png",".jpg":"image/jpeg",".jpeg":"image/jpeg",".webp":"image/webp",".gif":"image/gif"}
    return FileResponse(path,media_type=media.get(path.suffix.lower(),"application/octet-stream"),headers={"Cache-Control":"no-cache"})


@app.get("/panel/favicon")
def node_panel_favicon():
    path = _node_favicon_path()
    if not path:
        raise HTTPException(404)
    media={".ico":"image/x-icon",".png":"image/png",".jpg":"image/jpeg",".jpeg":"image/jpeg",".webp":"image/webp",".gif":"image/gif"}
    return FileResponse(path, media_type=media.get(path.suffix.lower(),"application/octet-stream"), headers={"Cache-Control":"no-cache"})

@app.post('/panel/manage/settings/dns01/test')
async def independent_settings_dns01_test(request: Request):
    require_node_panel_user(request, 'nodes.edit')
    form = await request.form()
    host = str(form.get('host') or '').strip().lower().rstrip('.')
    result = await asyncio.to_thread(_node_settings_dns01_test_sync, host)
    # STREAMFORGE_NODE_DNS01_TEST_AUTO_ISSUE_V1126: once the operator's CNAME
    # is publicly correct, do not wait up to the periodic TLS timer interval.
    if result.get('ok') and not result.get('certificate_ready') and not EXTERNAL_PROXY_MODE:
        manager.request_tls_reconcile(host, force_retry=True)
        result = dict(result)
        result['issuance_queued'] = True
        result['message'] = 'CNAME is correct and publicly visible. Certificate issuance queued automatically.'
    return JSONResponse(result)


@app.post('/panel/manage/settings/dns01/retry')
async def independent_settings_dns01_retry(request: Request):
    require_node_panel_user(request, 'nodes.edit')
    form = await request.form()
    host = str(form.get('host') or '').strip().lower().rstrip('.')
    if host not in _node_settings_tls_hosts():
        raise HTTPException(400, 'Hostname is not configured on this Node')
    if EXTERNAL_PROXY_MODE:
        return JSONResponse({'ok': True, 'queued': False, 'message': 'External proxy mode owns TLS.'})
    manager.request_tls_reconcile(host, force_retry=True)
    return JSONResponse({'ok': True, 'queued': True, 'message': 'Certificate retry queued. Previous ACME backoff for this hostname will be cleared.'})


@app.get('/panel/manage/settings', response_class=HTMLResponse)
def independent_settings(request: Request, message: str = '', error: str = ''):
    user=require_node_panel_user(request,'nodes.edit')
    return HTMLResponse(_settings_page(user,message,error))


@app.post('/panel/manage/settings')
async def independent_settings_save(request: Request):
    user=require_node_panel_user(request,'nodes.edit'); f=await request.form()
    try:
        if f.get('remove_youtube_cookies_file') is not None:
            _remove_node_youtube_cookies()
        _save_node_youtube_cookies(f.get('youtube_cookies_file'))
    except (ValueError, OSError) as exc:
        return HTMLResponse(_settings_page(user,error=str(exc)),400)
    previous_access = AccessSettingsPayload(
        panel_urls=list(manager.panel_urls), stream_urls=list(manager.stream_urls),
        access_slug=manager.access_slug, stream_slug=manager.stream_slug, stream_port=manager.stream_port,
        total_max_connections=manager.total_max_connections,
        client_session_reset_offline_minutes=manager.client_session_reset_offline_minutes,
        panel_ip_whitelist=manager.panel_ip_whitelist,
        panel_ip_blacklist=manager.panel_ip_blacklist,
        panel_asn_whitelist=manager.panel_asn_whitelist,
        panel_asn_blacklist=manager.panel_asn_blacklist,
        ip_whitelist=manager.ip_whitelist, ip_blacklist=manager.ip_blacklist,
        asn_whitelist=manager.asn_whitelist, asn_blacklist=manager.asn_blacklist,
    )
    try:
        # STREAMFORGE_NODE_SETTINGS_POST_RESPONSE_RECONCILE_V52: persist and
        # back-sync first; public listener/TLS changes are reconciled after the
        # response so saving Settings cannot tear down its own HTTPS request.
        manager.sync_access(AccessSettingsPayload(
            panel_urls=str(f.get('panel_urls') or '').replace('\r','').split('\n'),
            stream_urls=str(f.get('stream_urls') or '').replace('\r','').split('\n'),
            access_slug="",
            stream_slug="",
            stream_port=None,
            # STREAMFORGE_NODE_SETTINGS_HIDE_TOTAL_MAX_V51: this cluster-wide
            # limit is Main-managed; the standalone Node Settings UI no longer
            # rewrites it when saving unrelated settings.
            total_max_connections=int(manager.total_max_connections),
            client_session_reset_offline_minutes=max(1, min(10080, int(f.get('client_session_reset_offline_minutes') or 60))),
            panel_ip_whitelist=str(f.get('panel_ip_whitelist') or ''),
            panel_ip_blacklist=str(f.get('panel_ip_blacklist') or ''),
            panel_asn_whitelist=str(f.get('panel_asn_whitelist') or ''),
            panel_asn_blacklist=str(f.get('panel_asn_blacklist') or ''),
            ip_whitelist=str(f.get('ip_whitelist') or ''), ip_blacklist=str(f.get('ip_blacklist') or ''),
            asn_whitelist=str(f.get('asn_whitelist') or ''), asn_blacklist=str(f.get('asn_blacklist') or ''),
        ), apply_listeners=False)
        try:
            manager.back_sync_access_to_main()
        except RuntimeError:
            manager.sync_access(previous_access)
            raise
        manager.save_geo_settings(GeoSettingsPayload(
            provider=str(f.get('provider') or manager.geo_provider), auto_update=f.get('geo_auto_update') is not None,
            maxmind_account_id=str(f.get('maxmind_account_id') or manager.maxmind_account_id),
            maxmind_license_key=str(f.get('maxmind_license_key') or ''), ipinfo_token=str(f.get('ipinfo_token') or ''),
            remove_maxmind_key=f.get('remove_maxmind_key') is not None, remove_ipinfo_token=f.get('remove_ipinfo_token') is not None,
        ))
        operations = _node_operations_settings()
        operations['log_retention_days'] = max(1, min(3650, int(f.get('log_retention_days') or 30)))
        operations['metrics_retention_days'] = max(1, min(3650, int(f.get('metrics_retention_days') or 30)))
        operations['metrics_default_span_hours'] = max(1, min(operations['metrics_retention_days'] * 24, int(f.get('metrics_default_span_hours') or 24)))
        operations['metrics_sample_interval_seconds'] = max(5, min(3600, int(f.get('metrics_sample_interval_seconds') or 60)))
        OPERATIONS_SETTINGS_FILE.parent.mkdir(parents=True, exist_ok=True)
        temporary = OPERATIONS_SETTINGS_FILE.with_suffix('.tmp')
        temporary.write_text(json.dumps(operations, separators=(',', ':')), encoding='utf-8')
        temporary.replace(OPERATIONS_SETTINGS_FILE)
        manager.prune_event_logs(force=True)
        # STREAMFORGE_NODE_SETTINGS_SAFE_RETURN_V53: do not restart any
        # in-process listener from the request worker. The root TLS helper is
        # triggered independently and Nginx reloads gracefully.
        manager.request_tls_reconcile()
        manager.log('Node access settings updated and synchronized to Main',scope='settings',details=f'actor={user.username}')
        matched_prefix = _CURRENT_PANEL_PREFIX.get()
        public_root = matched_prefix if matched_prefix is not None else (f'/{manager.access_slug}' if manager.access_slug else '/')
        public_root = public_root or '/'
        target = '/panel/manage/settings?message=' + urllib.parse.quote_plus('Settings saved and synchronized to Main')
        # The response is sent first.  The background task writes a cross-process
        # reconcile request; the native control watcher reloads access.json and
        # performs the listener/TLS apply without recursive loopback HTTP.
        response = RedirectResponse(
            public_root, 303,
            background=BackgroundTask(manager.queue_control_access_reconcile_after_response),
        )
        _set_panel_route_cookie(response, request, target)
        return response
    except (ValueError, TypeError, RuntimeError) as exc:
        return HTMLResponse(_settings_page(user,error=str(exc)),400)



# STREAMFORGE_NODE_LIVE_SESSION_KILL_NO_NAV_V1043:
def _panel_session_kill_after_response(actor: str, session_id: str, source_key: str, user_id: str) -> None:
    """Run potentially slow/disruptive session cleanup only after HTTP ack."""
    cleaned_source = str(source_key or 'direct_node')
    try:
        if cleaned_source == 'direct_node':
            killed = manager.kill_viewer_session(session_id)
        else:
            result = manager.panel_control_request('POST', '/api/v1/node-control/viewers/kill', {
                'actor': actor, 'session_id': session_id, 'source_key': cleaned_source, 'user_id': user_id,
            }, timeout=12.0)
            killed = int(result.get('killed') or 0)
        manager.log(
            'Live session kill completed', scope='user', level='warning',
            details=f'actor={actor}; session_id={session_id}; source={cleaned_source}; killed={killed}',
        )
    except Exception as exc:
        # The browser has already received its acknowledgement, so a transient
        # Redis/Main cleanup failure is reported to Node logs instead of tearing
        # down the panel request and surfacing an Nginx 502 page.
        manager.log(
            'Live session kill failed', scope='user', level='error',
            details=f'actor={actor}; session_id={session_id}; source={cleaned_source}; error={exc}',
        )


@app.post('/panel/sessions/{session_id}/kill')
async def independent_session_kill(session_id: str, request: Request):
    user = require_node_panel_user(request, 'stream_users.kill')
    form = await request.form()
    source_key = str(form.get('source_key') or 'direct_node')
    user_id = str(form.get('user_id') or '')
    cleaned_session = _clean_live_session_kill_id(session_id)
    if not cleaned_session:
        if str(request.headers.get('x-streamforge-live-kill') or '') == '1':
            return JSONResponse({'ok': False, 'error': 'Session ID is required'}, status_code=400)
        return RedirectResponse('/panel/sessions?error=' + urllib.parse.quote_plus('Session ID is required'), 303)
    task = BackgroundTask(_panel_session_kill_after_response, user.username, cleaned_session, source_key, user_id)
    wants_json = (
        str(request.headers.get('x-streamforge-live-kill') or '').strip() == '1'
        or 'application/json' in str(request.headers.get('accept') or '').lower()
    )
    if wants_json:
        return JSONResponse(
            {'ok': True, 'accepted': True, 'session_id': cleaned_session},
            status_code=202, background=task,
        )
    return RedirectResponse(
        '/panel/sessions?message=' + urllib.parse.quote_plus('Kill request accepted'),
        303, background=task,
    )


def _node_xtream_user(username: str, password: str) -> NodeUserConfig | None:
    if not manager.panel_connected() and not manager.independent_mode:
        return None
    # STREAMFORGE_NODE_PLAYLIST_USER_AUTH_RELOAD_V123:
    # Public Gunicorn workers are separate processes from the Node Panel. Reload
    # the authoritative snapshot *before* username lookup so a newly-created or
    # renamed account is immediately visible on get.php/player_api/WebPlayer.
    manager.reload_users_if_changed()
    cleaned = str(username or "").strip().lower()
    with manager.lock:
        candidates = list(manager.users.values())
    for user in candidates:
        if not user.username or user.username.strip().lower() != cleaned:
            continue
        current = manager.valid_user(user.token)
        if current and current.password_hash and verify_scrypt_password(password, current.password_hash):
            return current
    return None


def _effective_user_channels(user: NodeUserConfig) -> list[NodeUserChannel]:
    manager.reload_channel_catalog_if_changed()
    profile = None
    profile_id = str(getattr(user, "playlist_profile_id", "") or "").strip()
    if profile_id:
        with manager.lock:
            profile = manager.playlists.get(profile_id)
        if profile and not profile.enabled:
            profile = None
    all_node_channels = bool(profile.all_node_channels) if profile else bool(user.all_node_channels)
    source_channels = list(profile.channels) if profile else list(user.channels)
    requested_channel_order = list(profile.playlist_order) if profile else list(user.playlist_order)
    requested_category_order = list(profile.playlist_category_order) if profile else list(user.playlist_category_order)
    if not all_node_channels:
        channels = source_channels
        if not manager.independent_mode:
            with manager.lock:
                local_runtimes = [
                    rt for rt in manager.channels.values()
                    if rt.config.catalog_owner == "local" and rt.config.enabled and rt.config.output_type == "hls"
                ]
            known = {item.key for item in channels}
            channels.extend(
                NodeUserChannel(
                    key=rt.config.key, name=rt.config.name, slug=rt.config.slug or rt.config.key,
                    category=(rt.config.category or "Uncategorized").strip() or "Uncategorized", categories=list(getattr(rt.config, 'categories', []) or []),
                    category_order=int(rt.config.category_order or 100000), channel_order=int(getattr(rt.config, 'channel_order', 100000) or 100000), logo_url=rt.config.logo_url or "",
                )
                for rt in local_runtimes if rt.config.key not in known
            )
    else:
        with manager.lock:
            runtimes = list(manager.channels.values())
        channels = [
            NodeUserChannel(
                key=rt.config.key, name=rt.config.name, slug=rt.config.slug or rt.config.key,
                category=(rt.config.category or "Uncategorized").strip() or "Uncategorized", categories=list(getattr(rt.config, 'categories', []) or []),
                category_order=int(rt.config.category_order or 100000), channel_order=int(getattr(rt.config, 'channel_order', 100000) or 100000), logo_url=rt.config.logo_url or "",
            )
            for rt in runtimes if rt.config.enabled and rt.config.output_type == "hls"
        ]

    with manager.lock:
        runtime_map = dict(manager.channels)
    display_ids = _node_channel_display_ids()

    # Main playlist snapshots carry both the Main channel ID and the key that
    # existed when the snapshot was copied.  The key contains the channel slug
    # (sf-<id>-<slug>), so a later slug rename can leave the Node runtime on an
    # older key while Main advertises the new key.  Resolve by stable stream ID
    # first, then by slug/name, and rewrite the snapshot item to the live key.
    # This repairs existing users at read time without requiring recreation.
    runtime_by_stream_id: dict[int, Any] = {}
    runtime_by_slug: dict[str, Any] = {}
    runtime_by_name: dict[str, Any] = {}
    for runtime_key, runtime in runtime_map.items():
        match = re.match(r"^sf-(\d+)-", str(runtime_key or ""))
        if match:
            runtime_by_stream_id.setdefault(int(match.group(1)), runtime)
        slug_key = str(getattr(runtime.config, "slug", "") or "").strip().lower()
        name_key = str(getattr(runtime.config, "name", "") or "").strip().lower()
        if slug_key:
            runtime_by_slug.setdefault(slug_key, runtime)
        if name_key:
            runtime_by_name.setdefault(name_key, runtime)

    enriched: list[NodeUserChannel] = []
    seen: set[str] = set()
    main_order = _main_category_order_map()
    for item in channels:
        rt = runtime_map.get(item.key)
        stable_stream_id: int | None = None
        if item.stream_id is not None:
            try:
                stable_stream_id = int(item.stream_id)
            except (TypeError, ValueError):
                stable_stream_id = None
        if stable_stream_id is None:
            saved_key_match = re.match(r"^sf-(\d+)-", str(item.key or ""))
            if saved_key_match:
                stable_stream_id = int(saved_key_match.group(1))
        if not rt and stable_stream_id is not None:
            rt = runtime_by_stream_id.get(stable_stream_id)
        if not rt:
            rt = runtime_by_slug.get(str(item.slug or "").strip().lower())
        if not rt:
            rt = runtime_by_name.get(str(item.name or "").strip().lower())

        resolved_key = str(rt.config.key) if rt else str(item.key)
        if resolved_key in seen:
            continue
        seen.add(resolved_key)
        if rt and rt.config.enabled and rt.config.output_type == 'hls':
            category = (rt.config.category or 'Uncategorized').strip() or 'Uncategorized'
            received_order = int(item.category_order if item.category_order is not None else 100000)
            received_order = main_order.get(category.lower(), received_order if received_order < 100000 else int(rt.config.category_order or 100000))
            enriched.append(item.model_copy(update={
                'stream_id': display_ids.get(resolved_key, item.stream_id),
                'key': resolved_key,
                'name': rt.config.name, 'slug': rt.config.slug or rt.config.key,
                'category': category, 'categories': list(getattr(rt.config, 'categories', []) or getattr(item, 'categories', []) or []), 'category_order': received_order,
                'channel_order': int(getattr(rt.config, 'channel_order', getattr(item, 'channel_order', 100000)) or 100000),
                'logo_url': rt.config.logo_url or item.logo_url,
            }))
        elif not rt:
            category = (item.category or 'Uncategorized').strip() or 'Uncategorized'
            received_order = int(item.category_order if item.category_order is not None else 100000)
            received_order = main_order.get(category.lower(), received_order)
            enriched.append(item.model_copy(update={'category': category, 'categories': list(getattr(item, 'categories', []) or []), 'category_order': received_order, 'channel_order': int(getattr(item, 'channel_order', 100000) or 100000)}))

    category_ranks: dict[str, int] = {}
    category_names: dict[str, str] = {}
    for item in enriched:
        display_name = (item.category or 'Uncategorized').strip() or 'Uncategorized'
        category_name = display_name.lower() or 'uncategorized'
        category_names.setdefault(category_name, display_name)
        rank = int(item.category_order if item.category_order is not None else 100000)
        category_ranks[category_name] = min(rank, category_ranks.get(category_name, rank))

    requested_categories: list[str] = []
    for value in requested_category_order or []:
        cleaned = str(value or '').strip().lower() or 'uncategorized'
        if cleaned in category_names and cleaned not in requested_categories:
            requested_categories.append(cleaned)
    default_categories = sorted(
        category_names,
        key=lambda key: (category_ranks.get(key, 100000), _category_sort_value(category_names[key]), key),
    )
    requested_categories.extend(key for key in default_categories if key not in requested_categories)
    category_position = {key: index for index, key in enumerate(requested_categories)}

    order: list[str] = []
    for key in requested_channel_order or []:
        cleaned = str(key or '').strip()
        if cleaned and cleaned not in order:
            order.append(cleaned)
    order_map = {key: index for index, key in enumerate(order)}
    return sorted(enriched, key=lambda item: (
        category_position.get((item.category or 'Uncategorized').strip().lower() or 'uncategorized', 100000),
        0 if item.key in order_map else 1,
        order_map.get(item.key, 999999),
        int(getattr(item, 'channel_order', 100000) or 100000),
        item.name.lower(), item.key,
    ))


def _channel_playback_ready(channel_key: str) -> bool:
    # STREAMFORGE_NODE_SINGLE_CHANNEL_READY_V65: hot playback/auth paths must
    # validate only the granted channel instead of rebuilding/scanning the
    # user's full catalogue for every cached-auth refresh.
    try:
        status = manager.status(channel_key)
    except (KeyError, ValueError):
        return False
    return bool(status.get("alive")) and bool(status.get("hls_ready"))


def _online_effective_user_channels(user: NodeUserConfig) -> list[NodeUserChannel]:
    """Filter a Node user's catalogue to live, playback-ready HLS outputs."""
    return [channel for channel in _effective_user_channels(user) if _channel_playback_ready(channel.key)]


# STREAMFORGE_NODE_WEBPLAYER_RUNTIME_SOURCE_LOOKUP_V1024:
def _node_channel_is_youtube_source(item: Any) -> bool:
    """Resolve source type from the live runtime, not the catalogue DTO.

    NodeUserChannel intentionally carries catalogue metadata only and has no
    input_url/input_urls fields.  The watch page must therefore look up the
    corresponding managed runtime before asking config_inputs() about sources.
    """
    key = str(getattr(item, "key", "") or "").strip()
    if not key:
        return False
    with manager.lock:
        runtime = manager.channels.get(key)
    if runtime is None:
        return False
    try:
        return any(is_youtube_url(source) for source in manager.config_inputs(runtime.config))
    except (AttributeError, TypeError, ValueError):
        return False


def _node_channel_categories(item: Any) -> list[str]:
    values: list[str] = []
    primary = str(getattr(item, "category", "") or "").strip()
    if primary:
        values.append(primary)
    for raw in list(getattr(item, "categories", []) or []):
        cleaned = str(raw or "").strip()
        if cleaned and cleaned not in values:
            values.append(cleaned)
    return values or ["Uncategorized"]


def _node_category_map(user: NodeUserConfig) -> dict[str, str]:
    names: list[str] = []
    for item in _online_effective_user_channels(user):
        for name in _node_channel_categories(item):
            if name not in names:
                names.append(name)
    return {name: str(index + 1) for index, name in enumerate(names)}


def _node_stream_id(channel: NodeUserChannel) -> int:
    if channel.stream_id and int(channel.stream_id) > 0:
        return int(channel.stream_id)
    return int(hashlib.sha256(channel.key.encode("utf-8")).hexdigest()[:7], 16)


def _direct_channel_hls_ready(channel: NodeUserChannel) -> bool:
    # STREAMFORGE_NODE_DIRECT_STREAM_HLS_FAST_READY_V1210:
    # Public direct-play startup must not wait for a supervisor RPC. The media
    # that Nginx will actually serve is the authoritative hot-path signal: an
    # existing playlist whose newest segment is fresh. This check is local
    # filesystem I/O only and validates exactly the selected channel.
    segment_time = 1
    with manager.lock:
        runtime = manager.channels.get(channel.key)
        if runtime is not None:
            try:
                segment_time = max(1, int(runtime.config.hls_segment_time or 1))
            except (TypeError, ValueError):
                segment_time = 1
    ready, fresh = manager._hls_output_state(channel.key, segment_time)
    return bool(ready and fresh)


def _node_channel_for_stream_id(user: NodeUserConfig, stream_id: int) -> NodeUserChannel | None:
    # STREAMFORGE_NODE_DIRECT_STREAM_SINGLE_READY_V1210:
    # A direct /live or /user/pass/id request needs one channel. v12.9 called
    # _online_effective_user_channels(), which performed manager.status() for
    # every assigned channel before comparing the requested stream_id. With
    # 100+ channels and supervisor-backed status reads this could turn a single
    # click into a multi-second (occasionally 10-15s) request. Resolve the
    # assigned catalogue in memory first, then validate only that channel's
    # fresh HLS output without a supervisor round-trip.
    wanted = int(stream_id)
    channel = next(
        (item for item in _effective_user_channels(user) if _node_stream_id(item) == wanted),
        None,
    )
    if channel is None or not _direct_channel_hls_ready(channel):
        return None
    return channel


def _node_server_info(request: Request) -> dict[str, Any]:
    parsed = urllib.parse.urlsplit(_node_public_base(request))
    return {
        "url": parsed.hostname or _request_host(request),
        "port": str(parsed.port or (443 if parsed.scheme == "https" else 80)),
        "https_port": "443",
        "server_protocol": parsed.scheme or "http",
        "rtmp_port": "0",
        "timezone": "UTC",
        "timestamp_now": int(time.time()),
        "time_now": time.strftime("%Y-%m-%d %H:%M:%S", time.gmtime()),
    }



