# STREAMFORGE_NODE_LOG_SEARCH_V1035:
# Keep the Node ring-buffer searchable without shipping every row to Main.
# Terms are ANDed across the same visible fields used by the Main Logs table.
def _node_log_matches_search(item: dict[str, Any], q: str) -> bool:
    normalized = " ".join(str(q or "").strip().split())[:240].casefold()
    terms = [term for term in normalized.split(" ") if term][:12]
    if not terms:
        return True
    haystack = "\n".join([
        str(manager.node_name or ""),
        str(item.get("scope") or ""),
        str(item.get("level") or ""),
        str(item.get("channel") or ""),
        str(item.get("user") or ""),
        str(item.get("message") or ""),
        str(item.get("details") or ""),
    ]).casefold()
    return all(term in haystack for term in terms)


@app.get("/api/v1/logs", dependencies=[Depends(authorized)])
def agent_logs(limit: int = 300, level: str = "", scope: str = "", q: str = ""):
    # STREAMFORGE_NODE_CLIENT_LOG_INLINE_SESSION_AGE_V1060: remote Main Logs and
    # the standalone Node panel receive the same folded Client-log presentation.
    items = _node_fold_playback_session_rows(manager.event_logs_snapshot())
    if level:
        items = [item for item in items if item.get("level") == level]
    if scope:
        items = [item for item in items if item.get("scope") == scope]
    if str(q or "").strip():
        items = [item for item in items if _node_log_matches_search(item, q)]
    safe_limit = int(limit or 0)
    selected_items = items if safe_limit <= 0 else items[:max(1, min(5000, safe_limit))]
    # STREAMFORGE_NODE_CLIENT_LOG_DURATION_API_V1045: Main receives the same
    # session age as the standalone Node Client log. v10.46 keeps the final age
    # after the viewer goes offline instead of dropping the column back to em dash.
    selected_items = [dict(item) for item in selected_items]
    client_rows = [item for item in selected_items if str(item.get("scope") or "").strip().lower() == "client"]
    duration_states = _node_client_log_duration_states(client_rows) if client_rows else []
    for item, state in zip(client_rows, duration_states):
        live_session_id = _node_client_log_session_id(item)
        if live_session_id:
            item["session_id"] = live_session_id
        if state:
            item["duration_seconds"] = int(state.get("duration_seconds") or 0)
            item["session_online"] = bool(state.get("online"))
    return {"ok": True, "total": len(items), "items": selected_items}


