@app.post("/api/v1/channels/{key}/logs/clear", dependencies=[Depends(authorized)])
def agent_channel_logs_clear(key: str):
    safe_key = manager.safe_key(key)
    manager.sync_event_logs_from_file()
    with manager.lock:
        previous = list(manager.event_logs)
        remaining = [item for item in previous if str(item.get("channel") or "").strip() != safe_key]
        cleared = len(previous) - len(remaining)
        manager.event_logs = deque(remaining, maxlen=NODE_EVENT_LOG_MAX)
        runtime = manager.channels.get(safe_key)
        if runtime:
            runtime.last_error = ""
    _rewrite_node_event_log_file()
    return {"ok": True, "cleared": cleared}


@app.post("/api/v1/logs/clear", dependencies=[Depends(authorized)])
def agent_logs_clear(log_type: str = "", level: str = "", scope: str = "", q: str = ""):
    # STREAMFORGE_NODE_SCOPED_LOG_CLEAR_V66:
    manager.sync_event_logs_from_file()
    # Clear only the selected Main Logs tab/filter instead of wiping the
    # entire Node ring buffer. With no filters this remains backward-compatible.
    selected = str(log_type or "").strip().lower()
    system_scopes = {"system", "node", "update", "settings"}
    excluded_activity = {"auth", "client", *system_scopes}

    def matches(item):
        item_scope = str(item.get("scope") or "system")
        item_level = str(item.get("level") or "info")
        if selected == "access" and item_scope != "auth":
            return False
        if selected == "client" and item_scope != "client":
            return False
        if selected == "system" and item_scope not in system_scopes:
            return False
        if selected == "activity" and item_scope in excluded_activity:
            return False
        if scope and item_scope != scope:
            return False
        if level and item_level != level:
            return False
        if str(q or "").strip() and not _node_log_matches_search(item, q):
            return False
        return True

    with manager.lock:
        previous = list(manager.event_logs)
        if not selected and not scope and not level and not str(q or "").strip():
            remaining = []
        else:
            remaining = [item for item in previous if not matches(item)]
        cleared = len(previous) - len(remaining)
        manager.event_logs = deque(remaining, maxlen=NODE_EVENT_LOG_MAX)
    _rewrite_node_event_log_file()
    manager.log("Node logs cleared", scope="system", details={"cleared": cleared, "log_type": selected, "scope": scope, "level": level, "q": str(q or "")[:240]})
    return {"ok": True, "cleared": cleared}

