_HEALTH_CAPABILITY_CACHE: dict[str, Any] = {"checked_at": 0.0, "values": {}}
_HEALTH_CAPABILITY_LOCK = threading.RLock()


def _health_capabilities() -> dict[str, str]:
    now = time.monotonic()
    with _HEALTH_CAPABILITY_LOCK:
        cached = dict(_HEALTH_CAPABILITY_CACHE.get("values") or {})
        if cached and now - float(_HEALTH_CAPABILITY_CACHE.get("checked_at") or 0.0) < 300:
            return cached
        values: dict[str, str] = {}
        for family in ("h264", "h265"):
            try:
                values[family] = manager.auto_encoder(family)
            except Exception as exc:
                values[family] = f"unavailable: {exc}"
        _HEALTH_CAPABILITY_CACHE["checked_at"] = now
        _HEALTH_CAPABILITY_CACHE["values"] = values
        return dict(values)


# STREAMFORGE_NODE_CARD_STRICT_DELIVERY_COUNTS_V45:
# STREAMFORGE_NODE_CARD_WAITING_AS_DOWN_V46: Main folds this detailed Waiting count into Down on summary cards.
def _node_card_delivery_counts(owner: str | None = None) -> dict[str, int]:
    """Count Node channels by playable delivery rather than FFmpeg liveness."""
    wanted_owner = str(owner or "").strip().lower()
    with manager.lock:
        configs = [
            (key, runtime.config)
            for key, runtime in manager.channels.items()
            if not wanted_owner or str(getattr(runtime.config, "catalog_owner", "main") or "main").strip().lower() == wanted_owner
        ]
    counts = {"total": len(configs), "up": 0, "waiting": 0, "down": 0, "active": 0}
    for key, config in configs:
        status = manager.status(key)
        if bool(status.get("alive")):
            counts["active"] += 1
        delivery = _node_channel_delivery_status(config, status)
        counts[delivery if delivery in {"up", "waiting", "down"} else "down"] += 1
    return counts


@app.get("/api/v1/status/quick", dependencies=[Depends(authorized)])
def quick_status():
    """Return the Node-card payload without expensive health side effects."""
    delivery_counts = _node_card_delivery_counts()
    active_channels = int(delivery_counts["active"])
    active_connections = int(manager.total_active_connections())
    return {
        "ok": True,
        "status": "online",
        "version": VERSION,
        "hostname": os.uname().nodename,
        "metrics": manager.metrics(),
        "active_channels": active_channels,
        "up_channels": int(delivery_counts["up"]),
        "waiting_channels": int(delivery_counts["waiting"]),
        "down_channels": int(delivery_counts["down"]),
        "viewer_stats": {"total_users": active_connections},
        "active_connections": active_connections,
        "total_max_connections": int(manager.total_max_connections),
        "panel_urls": list(manager.panel_urls),
        "stream_urls": list(manager.stream_urls),
        "stream_port": int(manager.stream_port),
        "control_port": int(CONTROL_PORT),
        "node_mode": NODE_MODE,
        "external_proxy_mode": bool(EXTERNAL_PROXY_MODE),
        # STREAMFORGE_NODE_DNS01_STATUS_QUICK_V41: lets Main show the one-time
        # CNAME instruction even before HTTPS is available on this Node.
        "managed_tls": manager.tls_status(),
    }


# STREAMFORGE_NODE_DNS01_CONTROL_TEST_V82: authenticated Main control-plane
# test endpoint. It deliberately reuses the exact Node Settings resolver logic
# so Main and Node can never disagree because they tested from different hosts.
@app.post("/api/v1/tls/dns01/test", dependencies=[Depends(authorized)])
async def tls_dns01_test(request: Request):
    try:
        payload = await request.json()
    except Exception:
        payload = {}
    host = str(payload.get("host") or "").strip().lower().rstrip(".") if isinstance(payload, dict) else ""
    result = await asyncio.to_thread(_node_settings_dns01_test_sync, host)
    if result.get("ok") and not result.get("certificate_ready") and not EXTERNAL_PROXY_MODE:
        manager.request_tls_reconcile(host, force_retry=True)
        result = dict(result)
        result["issuance_queued"] = True
        result["message"] = "CNAME is correct and publicly visible. Certificate issuance queued automatically."
    return JSONResponse(result)


# STREAMFORGE_NODE_TLS_RECONCILE_API_V42: Main/Node Panel can request an
# immediate root TLS reconciliation without blocking this Gunicorn worker.
# STREAMFORGE_NODE_DNS01_RETRY_VALIDATE_V82: when Main supplies a hostname,
# validate it against the Node's own TLS host list rather than Main's cached
# status. Older callers may omit the body and still reconcile all configured hosts.
@app.post("/api/v1/tls/reconcile", dependencies=[Depends(authorized)])
async def tls_reconcile(request: Request):
    try:
        payload = await request.json()
    except Exception:
        payload = {}
    host = str(payload.get("host") or "").strip().lower().rstrip(".") if isinstance(payload, dict) else ""
    if host and host not in _node_settings_tls_hosts():
        raise HTTPException(400, "Hostname is not configured on this Node")
    if EXTERNAL_PROXY_MODE:
        return {"ok": True, "queued": False, "message": "External proxy mode owns TLS"}
    manager.request_tls_reconcile(host, force_retry=bool(host))
    return {
        "ok": True,
        "queued": True,
        "message": "Node certificate retry queued" + ("; previous ACME backoff cleared" if host else ""),
        "host": host,
        "managed_tls": manager.tls_status(),
    }


