def protect_local_channel_from_main_api(key: str, *, allow_missing: bool = True) -> None:
    safe = manager.safe_key(key)
    with manager.lock:
        runtime = manager.channels.get(safe)
    if runtime and runtime.config.catalog_owner == "local":
        raise HTTPException(409, "A Node-local channel already uses this key")
    if not runtime and not allow_missing:
        raise HTTPException(404, "Main Server channel not found")


