@app.post("/api/v1/channel-logos/{filename}/sync", dependencies=[Depends(authorized)])
def sync_channel_logo_file(filename: str, payload: ChannelLogoSyncPayload):
    safe = Path(filename).name
    extension = Path(safe).suffix.lower()
    stem = Path(safe).stem
    if safe != filename or extension not in {".png", ".jpg", ".jpeg", ".webp", ".gif"} or _local_slug(stem) != stem:
        raise HTTPException(400, "Invalid channel logo filename")
    try:
        data = base64.b64decode(payload.content_base64, validate=True)
    except (ValueError, TypeError) as exc:
        raise HTTPException(400, "Invalid channel logo data") from exc
    if not data or len(data) > 2 * 1024 * 1024:
        raise HTTPException(400, "Channel logo must be between 1 byte and 2 MB")
    valid = (
        (extension == ".png" and data.startswith(b"\x89PNG\r\n\x1a\n"))
        or (extension in {".jpg", ".jpeg"} and data.startswith(b"\xff\xd8\xff"))
        or (extension == ".webp" and len(data) >= 12 and data[:4] == b"RIFF" and data[8:12] == b"WEBP")
        or (extension == ".gif" and data.startswith((b"GIF87a", b"GIF89a")))
    )
    if not valid:
        raise HTTPException(400, "Channel logo content does not match its extension")
    CHANNEL_LOGO_ROOT.mkdir(parents=True, exist_ok=True)
    target = CHANNEL_LOGO_ROOT / safe
    temporary = CHANNEL_LOGO_ROOT / f".{safe}.{secrets.token_hex(4)}.tmp"
    temporary.write_bytes(data)
    os.chmod(temporary, 0o644)
    temporary.replace(target)
    for other_extension in (".png", ".jpg", ".jpeg", ".webp", ".gif"):
        other = CHANNEL_LOGO_ROOT / f"{stem}{other_extension}"
        if other != target:
            other.unlink(missing_ok=True)
    return {"ok": True, "logo_url": f"/channel-logos/{safe}", "bytes": len(data)}


# STREAMFORGE_NODE_WEBPLAYER_BRAND_ASSET_SYNC_V1158:
def _brand_sync_target(brand_id: str, kind: str, filename: str = "") -> Path:
    safe_id = re.sub(r"[^a-z0-9_-]+", "", str(brand_id or "").strip().lower())[:40]
    if not safe_id:
        raise HTTPException(400, "Invalid Web Player brand id")
    WEBPLAYER_BRAND_ROOT.mkdir(parents=True, exist_ok=True)
    if kind == "download":
        return WEBPLAYER_BRAND_ROOT / f"{safe_id}-download.bin"
    suffix = Path(filename).suffix.lower()
    allowed = {"logo": {".png", ".jpg", ".jpeg", ".webp", ".gif"}, "favicon": {".ico", ".png", ".jpg", ".jpeg", ".webp", ".gif"}}
    if suffix not in allowed.get(kind, set()):
        raise HTTPException(400, f"Invalid Web Player brand {kind} file")
    return WEBPLAYER_BRAND_ROOT / f"{safe_id}-{kind}{suffix}"


@app.post("/api/v1/webplayer-brand/{brand_id}/{kind}/sync", dependencies=[Depends(authorized)])
async def sync_webplayer_brand_asset(brand_id: str, kind: str, request: Request, x_streamforge_filename: str = Header(default="")):
    if kind not in {"logo", "favicon", "download"}:
        raise HTTPException(404)
    display_name = Path(urllib.parse.unquote(str(x_streamforge_filename or "")).replace("\\", "/")).name.strip()
    data = await request.body()
    limit = 100 * 1024 * 1024 if kind == "download" else 2 * 1024 * 1024
    if not data or len(data) > limit:
        raise HTTPException(400, f"Web Player brand {kind} file size is invalid")
    target = _brand_sync_target(brand_id, kind, display_name)
    if kind != "download":
        ext = target.suffix.lower()
        valid = (
            (ext == ".ico" and data.startswith(b"\x00\x00\x01\x00"))
            or (ext == ".png" and data.startswith(b"\x89PNG\r\n\x1a\n"))
            or (ext in {".jpg", ".jpeg"} and data.startswith(b"\xff\xd8\xff"))
            or (ext == ".webp" and len(data) >= 12 and data[:4] == b"RIFF" and data[8:12] == b"WEBP")
            or (ext == ".gif" and data.startswith((b"GIF87a", b"GIF89a")))
        )
        if not valid:
            raise HTTPException(400, f"Web Player brand {kind} content does not match its extension")
        prefix = f"{re.sub(r'[^a-z0-9_-]+', '', brand_id.lower())[:40]}-{kind}"
        for other in WEBPLAYER_BRAND_ROOT.glob(prefix + ".*"):
            if other != target:
                other.unlink(missing_ok=True)
    temporary = target.with_name(f".{target.name}.{secrets.token_hex(4)}.tmp")
    temporary.write_bytes(data)
    os.chmod(temporary, 0o644)
    temporary.replace(target)
    return {"ok": True, "filename": display_name or target.name, "bytes": len(data), "asset": target.name}


@app.delete("/api/v1/webplayer-brand/{brand_id}/{kind}/sync", dependencies=[Depends(authorized)])
def remove_webplayer_brand_asset(brand_id: str, kind: str):
    safe_id = re.sub(r"[^a-z0-9_-]+", "", str(brand_id or "").strip().lower())[:40]
    if not safe_id or kind not in {"logo", "favicon", "download"}:
        raise HTTPException(404)
    if kind == "download":
        (WEBPLAYER_BRAND_ROOT / f"{safe_id}-download.bin").unlink(missing_ok=True)
    else:
        for target in WEBPLAYER_BRAND_ROOT.glob(f"{safe_id}-{kind}.*"):
            target.unlink(missing_ok=True)
    return {"ok": True, "removed": True}


# STREAMFORGE_NODE_WEBPLAYER_DOWNLOAD_SYNC_V3045:
@app.post("/api/v1/webplayer-download/sync", dependencies=[Depends(authorized)])
async def sync_webplayer_download_file(
    request: Request,
    x_streamforge_filename: str = Header(default=""),
):
    display_name = Path(urllib.parse.unquote(str(x_streamforge_filename or "")).replace("\\", "/")).name.strip()
    if not display_name or display_name in {".", ".."} or len(display_name) > 180:
        raise HTTPException(400, "Invalid Web Player download filename")
    data = await request.body()
    if not data or len(data) > 100 * 1024 * 1024:
        raise HTTPException(400, "Web Player download must be between 1 byte and 100 MB")
    WEBPLAYER_DOWNLOAD_FILE.parent.mkdir(parents=True, exist_ok=True)
    temporary = WEBPLAYER_DOWNLOAD_FILE.with_name(f".{WEBPLAYER_DOWNLOAD_FILE.name}.{secrets.token_hex(4)}.tmp")
    temporary.write_bytes(data)
    os.chmod(temporary, 0o644)
    temporary.replace(WEBPLAYER_DOWNLOAD_FILE)
    # STREAMFORGE_NODE_WEBPLAYER_DOWNLOAD_ACCESS_PATCH_V127:
    # Main calls this immediately after authoritative access/brand sync. Another
    # control worker can receive this request with stale aliases/brands, so patch
    # only the owned download field instead of full-saving its stale snapshot.
    manager.patch_access_file({"webplayer_download_name": display_name})
    manager.load_access()
    return {"ok": True, "filename": display_name, "bytes": len(data)}


@app.delete("/api/v1/webplayer-download/sync", dependencies=[Depends(authorized)])
def remove_webplayer_download_file():
    WEBPLAYER_DOWNLOAD_FILE.unlink(missing_ok=True)
    # STREAMFORGE_NODE_WEBPLAYER_DOWNLOAD_ACCESS_PATCH_V127:
    manager.patch_access_file({"webplayer_download_name": ""})
    manager.load_access()
    return {"ok": True, "removed": True}


@app.post("/api/v1/node-logo/{filename}/sync", dependencies=[Depends(authorized)])
def sync_node_logo_file(filename: str, payload: ChannelLogoSyncPayload):
    safe = Path(filename).name
    extension = Path(safe).suffix.lower()
    if safe != filename or extension not in {".png", ".jpg", ".jpeg", ".webp", ".gif"}:
        raise HTTPException(400, "Invalid Node logo filename")
    try:
        data = base64.b64decode(payload.content_base64, validate=True)
    except (ValueError, TypeError) as exc:
        raise HTTPException(400, "Invalid Node logo data") from exc
    if not data or len(data) > 2 * 1024 * 1024:
        raise HTTPException(400, "Node logo must be between 1 byte and 2 MB")
    valid = (
        (extension == ".png" and data.startswith(b"\x89PNG\r\n\x1a\n"))
        or (extension in {".jpg", ".jpeg"} and data.startswith(b"\xff\xd8\xff"))
        or (extension == ".webp" and len(data) >= 12 and data[:4] == b"RIFF" and data[8:12] == b"WEBP")
        or (extension == ".gif" and data.startswith((b"GIF87a", b"GIF89a")))
    )
    if not valid:
        raise HTTPException(400, "Node logo content does not match its extension")
    NODE_LOGO_ROOT.mkdir(parents=True, exist_ok=True)
    target = NODE_LOGO_ROOT / safe
    temporary = NODE_LOGO_ROOT / f".{safe}.{secrets.token_hex(4)}.tmp"
    temporary.write_bytes(data)
    os.chmod(temporary, 0o644)
    temporary.replace(target)
    return {"ok": True, "logo_url": f"/node-logos/{safe}", "bytes": len(data)}


