@app.get("/api/v1/channel-statuses", dependencies=[Depends(authorized)])
def channel_statuses():
    manager.reload_channel_catalog_if_changed()
    with manager.lock:
        keys = list(manager.channels)
    error_map = _node_recent_channel_errors()
    channels: dict[str, dict[str, Any]] = {}
    supervisor_rows: dict[str, dict[str, Any]] = {}
    if not NODE_CHANNEL_OWNER and NODE_DEDICATED_CHANNEL_SUPERVISOR:
        try:
            supervisor_rows = manager._supervisor_statuses(force=True)
        except RuntimeError:
            supervisor_rows = {}
    for key in keys:
        item = dict(supervisor_rows.get(key) or manager.status(key))
        recent = error_map.get(key, [])
        item["error_count"] = len(recent)
        item["restart_count"] = sum(
            1 for event in recent
            if "restart" in str(event.get("message") or "").lower()
            or "ffmpeg exited" in str(event.get("message") or "").lower()
        )
        channels[key] = item
    return {"channels": channels}


@app.get("/api/v1/channels/{key}/status", dependencies=[Depends(authorized)])
def channel_status(key: str):
    try:
        payload = dict(manager.status(key))
        # STREAMFORGE_REPLICA_NODE_CHANNEL_UPTIME_V63R7:
        # Main's on-demand Stream Info live check can show Node host uptime and
        # this channel's FFmpeg uptime from one authenticated request.
        try:
            payload["node_uptime_seconds"] = int(float(Path("/proc/uptime").read_text().split()[0]))
        except (OSError, ValueError, IndexError):
            payload["node_uptime_seconds"] = int(manager.metrics().get("uptime_seconds") or 0)
        return payload
    except ValueError as exc:
        raise HTTPException(400, str(exc)) from exc


