@app.get("/api/v1/hls/{key}/{filename}", dependencies=[Depends(authorized)])
def hls_file(key: str, filename: str):
    try:
        key = manager.safe_key(key)
    except ValueError as exc:
        raise HTTPException(404) from exc
    safe = Path(filename).name
    if safe != filename or not safe.endswith((".m3u8", ".ts", ".m4s", ".aac", ".mp3", ".key")):
        raise HTTPException(404)
    path = HLS_ROOT / key / safe
    if not path.is_file():
        raise HTTPException(404)
    media = {".m3u8": "application/vnd.apple.mpegurl", ".ts": "video/mp2t", ".m4s": "video/iso.segment", ".aac": "audio/aac", ".mp3": "audio/mpeg", ".key": "application/octet-stream"}
    return FileResponse(path, media_type=media.get(path.suffix.lower(), "application/octet-stream"), headers={"Cache-Control": "no-store", "Access-Control-Allow-Origin": "*"})

